// PIMPL (Pointer to Implementation) is a Bridge variant
// Header file only shows interface, implementation is hidden

class Widget {
    class Impl;  // Forward declaration
    unique_ptr<Impl> pImpl;  // The bridge to implementation

public:
    Widget();
    ~Widget();

    // Public interface
    void setWidth(int w);
    void setHeight(int h);
    void setColor(const string& c);
    void draw() const;
    int getArea() const;

    // Move semantics
    Widget(Widget&& other) noexcept;
    Widget& operator=(Widget&& other) noexcept;
};

// Implementation (normally in .cpp file)
class Widget::Impl {
public:
    int width = 0;
    int height = 0;
    string color = "white";
    vector<string> children;

    void validate() const {
        if (width < 0 || height < 0) throw invalid_argument("Negative dimension");
    }
};

Widget::Widget() : pImpl(make_unique<Impl>()) {}
Widget::~Widget() = default;

void Widget::setWidth(int w) { 
    pImpl->width = w; 
    pImpl->validate();
}
void Widget::setHeight(int h) { 
    pImpl->height = h; 
    pImpl->validate();
}
void Widget::setColor(const string& c) { pImpl->color = c; }

void Widget::draw() const {
    cout << "Widget (" << pImpl->width << "x" << pImpl->height 
         << ", " << pImpl->color << ")\n";
}

int Widget::getArea() const {
    return pImpl->width * pImpl->height;
}

Widget::Widget(Widget&& other) noexcept = default;
Widget& Widget::operator=(Widget&& other) noexcept = default;

