// Component Interface
class FileSystemComponent {
public:
    virtual ~FileSystemComponent() = default;
    virtual string getName() const = 0;
    virtual int getSize() const = 0;
    virtual void display(int indent = 0) const = 0;
    virtual void add(shared_ptr<FileSystemComponent> component) {
        throw runtime_error("Cannot add to leaf");
    }
    virtual void remove(shared_ptr<FileSystemComponent> component) {
        throw runtime_error("Cannot remove from leaf");
    }
};

// Leaf: File
class File : public FileSystemComponent {
    string name;
    int size;
public:
    File(const string& n, int s) : name(n), size(s) {}
    string getName() const override { return name; }
    int getSize() const override { return size; }
    void display(int indent = 0) const override {
        cout << string(indent, ' ') << "📄 " << name 
             << " (" << size << " bytes)\n";
    }
};

// Composite: Directory
class Directory : public FileSystemComponent {
    string name;
    vector<shared_ptr<FileSystemComponent>> children;
public:
    Directory(const string& n) : name(n) {}
    string getName() const override { return name; }

    int getSize() const override {
        int total = 0;
        for (auto& child : children) {
            total += child->getSize();
        }
        return total;
    }

    void display(int indent = 0) const override {
        cout << string(indent, ' ') << "📁 " << name 
             << " (" << getSize() << " bytes)\n";
        for (auto& child : children) {
            child->display(indent + 2);
        }
    }

    void add(shared_ptr<FileSystemComponent> component) override {
        children.push_back(component);
    }

    void remove(shared_ptr<FileSystemComponent> component) override {
        children.erase(
            remove_if(children.begin(), children.end(),
                [&component](const auto& c) { return c == component; }),
            children.end()
        );
    }
};

int main() {
    // Build file system tree
    auto root = make_shared<Directory>("root");
    auto docs = make_shared<Directory>("documents");
    auto pics = make_shared<Directory>("pictures");

    root->add(docs);
    root->add(pics);

    docs->add(make_shared<File>("resume.pdf", 45000));
    docs->add(make_shared<File>("cover_letter.docx", 12000));

    auto work = make_shared<Directory>("work");
    docs->add(work);
    work->add(make_shared<File>("project_plan.pdf", 89000));
    work->add(make_shared<File>("budget.xlsx", 34000));

    pics->add(make_shared<File>("vacation.jpg", 2500000));
    pics->add(make_shared<File>("profile.png", 450000));

    // Display entire tree
    root->display();

    cout << "\nTotal size: " << root->getSize() << " bytes\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Forward declarations for Visitor
class Circle;
class Rectangle;
class Group;

// Visitor Interface
class ShapeVisitor {
public:
    virtual ~ShapeVisitor() = default;
    virtual void visit(Circle& c) = 0;
    virtual void visit(Rectangle& r) = 0;
    virtual void visit(Group& g) = 0;
};

// Component
class Shape {
public:
    virtual ~Shape() = default;
    virtual void draw() const = 0;
    virtual void accept(ShapeVisitor& visitor) = 0;
    virtual void add(shared_ptr<Shape> shape) {
        throw runtime_error("Cannot add to leaf shape");
    }
};

// Leaf: Circle
class Circle : public Shape {
    float x, y, radius;
public:
    Circle(float x, float y, float r) : x(x), y(y), radius(r) {}
    void draw() const override {
        cout << "Circle at (" << x << "," << y << ") r=" << radius << "\n";
    }
    void accept(ShapeVisitor& visitor) override { visitor.visit(*this); }
    float getRadius() const { return radius; }
};

// Leaf: Rectangle
class Rectangle : public Shape {
    float x, y, w, h;
public:
    Rectangle(float x, float y, float w, float h) : x(x), y(y), w(w), h(h) {}
    void draw() const override {
        cout << "Rectangle at (" << x << "," << y << ") " << w << "x" << h << "\n";
    }
    void accept(ShapeVisitor& visitor) override { visitor.visit(*this); }
    float getArea() const { return w * h; }
};

// Composite: Group
class Group : public Shape {
    vector<shared_ptr<Shape>> children;
public:
    void draw() const override {
        cout << "Group containing:\n";
        for (auto& child : children) {
            child->draw();
        }
    }
    void accept(ShapeVisitor& visitor) override { visitor.visit(*this); }
    void add(shared_ptr<Shape> shape) override { children.push_back(shape); }
    const vector<shared_ptr<Shape>>& getChildren() const { return children; }
};

// Concrete Visitor: Export to SVG
class SVGExporter : public ShapeVisitor {
    stringstream svg;
public:
    void visit(Circle& c) override {
        svg << "  <circle />\n";
    }
    void visit(Rectangle& r) override {
        svg << "  <rect />\n";
    }
    void visit(Group& g) override {
        svg << "  <g>\n";
        for (auto& child : g.getChildren()) {
            child->accept(*this);
        }
        svg << "  </g>\n";
    }
    string getSVG() const { return svg.str(); }
};

// Concrete Visitor: Calculate total area
class AreaCalculator : public ShapeVisitor {
    float totalArea = 0;
public:
    void visit(Circle& c) override {
        totalArea += 3.14159f * c.getRadius() * c.getRadius();
    }
    void visit(Rectangle& r) override {
        totalArea += r.getArea();
    }
    void visit(Group& g) override {
        for (auto& child : g.getChildren()) {
            child->accept(*this);
        }
    }
    float getTotalArea() const { return totalArea; }
};

int main() {
    auto scene = make_shared<Group>();

    auto shapes = make_shared<Group>();
    shapes->add(make_shared<Circle>(10, 10, 5));
    shapes->add(make_shared<Rectangle>(0, 0, 20, 30));

    auto moreShapes = make_shared<Group>();
    moreShapes->add(make_shared<Circle>(50, 50, 10));

    scene->add(shapes);
    scene->add(moreShapes);

    cout << "=== Drawing ===\n";
    scene->draw();

    cout << "\n=== SVG Export ===\n";
    SVGExporter svg;
    scene->accept(svg);
    cout << svg.getSVG();

    cout << "\n=== Area Calculation ===\n";
    AreaCalculator calc;
    scene->accept(calc);
    cout << "Total area: " << calc.getTotalArea() << "\n";

    return 0;
}

