#include <bits/stdc++.h>
using namespace std;

// Component
class DataSource {
public:
    virtual ~DataSource() = default;
    virtual void write(const string& data) = 0;
    virtual string read() = 0;
};

// Concrete Component: File storage
class FileDataSource : public DataSource {
    string filename;
    string data;
public:
    FileDataSource(const string& f) : filename(f) {}
    void write(const string& d) override {
        data = d;
        cout << "Writing to file: " << filename << "\n";
    }
    string read() override {
        cout << "Reading from file: " << filename << "\n";
        return data;
    }
};

// Base Decorator
class DataSourceDecorator : public DataSource {
protected:
    unique_ptr<DataSource> wrappee;
public:
    DataSourceDecorator(unique_ptr<DataSource> ds) : wrappee(move(ds)) {}
    void write(const string& data) override { wrappee->write(data); }
    string read() override { return wrappee->read(); }
};

// Encryption Decorator
class EncryptionDecorator : public DataSourceDecorator {
    string encrypt(const string& data) {
        string result = data;
        for (char& c : result) c = c + 1;  // Simple Caesar cipher
        return result;
    }
    string decrypt(const string& data) {
        string result = data;
        for (char& c : result) c = c - 1;
        return result;
    }
public:
    EncryptionDecorator(unique_ptr<DataSource> ds) : DataSourceDecorator(move(ds)) {}
    void write(const string& data) override {
        cout << "[Encrypting data...]\n";
        wrappee->write(encrypt(data));
    }
    string read() override {
        cout << "[Decrypting data...]\n";
        return decrypt(wrappee->read());
    }
};

// Compression Decorator
class CompressionDecorator : public DataSourceDecorator {
    string compress(const string& data) {
        return "COMPRESSED[" + data + "]";  // Simplified
    }
    string decompress(const string& data) {
        // Remove COMPRESSED[ and ] markers
        if (data.substr(0, 11) == "COMPRESSED[") {
            return data.substr(11, data.size() - 12);
        }
        return data;
    }
public:
    CompressionDecorator(unique_ptr<DataSource> ds) : DataSourceDecorator(move(ds)) {}
    void write(const string& data) override {
        cout << "[Compressing data...]\n";
        wrappee->write(compress(data));
    }
    string read() override {
        cout << "[Decompressing data...]\n";
        return decompress(wrappee->read());
    }
};

// Logging Decorator
class LoggingDecorator : public DataSourceDecorator {
public:
    LoggingDecorator(unique_ptr<DataSource> ds) : DataSourceDecorator(move(ds)) {}
    void write(const string& data) override {
        cout << "[LOG] Write operation started at " 
             << chrono::system_clock::now().time_since_epoch().count() << "\n";
        wrappee->write(data);
        cout << "[LOG] Write operation completed\n";
    }
    string read() override {
        cout << "[LOG] Read operation started\n";
        auto result = wrappee->read();
        cout << "[LOG] Read operation completed, " << result.size() << " bytes\n";
        return result;
    }
};

int main() {
    // Stack decorators: Logging → Compression → Encryption → File
    auto source = make_unique<LoggingDecorator>(
        make_unique<CompressionDecorator>(
            make_unique<EncryptionDecorator>(
                make_unique<FileDataSource>("data.txt")
            )
        )
    );

    string original = "Hello, World!";
    cout << "Original: " << original << "\n\n";

    source->write(original);
    cout << "\n";

    string retrieved = source->read();
    cout << "\nRetrieved: " << retrieved << "\n";

    return 0;
}

