using namespace std;

// Subject
class DataService {
public:
    virtual ~DataService() = default;
    virtual vector<int> fetchData(const string& query) = 0;
    virtual double computeExpensive(int n) = 0;
};

// Real Service
class DatabaseService : public DataService {
public:
    vector<int> fetchData(const string& query) override {
        cout << "[DB] Executing query: " << query << "\n";
        this_thread::sleep_for(chrono::milliseconds(200));  // Slow DB
        return {1, 2, 3, 4, 5};  // Simulated result
    }

    double computeExpensive(int n) override {
        cout << "[COMPUTE] Calculating fib(" << n << ")...\n";
        this_thread::sleep_for(chrono::milliseconds(100));
        if (n <= 1) return n;
        double a = 0, b = 1;
        for (int i = 2; i <= n; i++) {
            double temp = a + b;
            a = b;
            b = temp;
        }
        return b;
    }
};

// Caching Proxy
class CachingProxy : public DataService {
    unique_ptr<DataService> realService;
    unordered_map<string, vector<int>> dataCache;
    unordered_map<int, double> computeCache;
    mutable mutex cacheMutex;

public:
    CachingProxy(unique_ptr<DataService> service) : realService(move(service)) {}

    vector<int> fetchData(const string& query) override {
        {
            lock_guard<mutex> lock(cacheMutex);
            auto it = dataCache.find(query);
            if (it != dataCache.end()) {
                cout << "[CACHE] Returning cached result for: " << query << "\n";
                return it->second;
            }
        }

        auto result = realService->fetchData(query);
        {
            lock_guard<mutex> lock(cacheMutex);
            dataCache[query] = result;
        }
        return result;
    }

    double computeExpensive(int n) override {
        {
            lock_guard<mutex> lock(cacheMutex);
            auto it = computeCache.find(n);
            if (it != computeCache.end()) {
                cout << "[CACHE] Returning cached fib(" << n << ") = " << it->second << "\n";
                return it->second;
            }
        }

        double result = realService->computeExpensive(n);
        {
            lock_guard<mutex> lock(cacheMutex);
            computeCache[n] = result;
        }
        return result;
    }

    void clearCache() {
        lock_guard<mutex> lock(cacheMutex);
        dataCache.clear();
        computeCache.clear();
        cout << "[CACHE] Cleared\n";
    }

    void printStats() const {
        lock_guard<mutex> lock(cacheMutex);
        cout << "[CACHE] Stats: " << dataCache.size() << " data entries, "
             << computeCache.size() << " compute entries\n";
    }
};

int main() {
    auto service = make_unique<CachingProxy>(make_unique<DatabaseService>());

    cout << "=== First calls (uncached) ===\n";
    auto r1 = service->fetchData("SELECT * FROM users");
    auto c1 = service->computeExpensive(35);

    cout << "\n=== Second calls (cached) ===\n";
    auto r2 = service->fetchData("SELECT * FROM users");
    auto c2 = service->computeExpensive(35);

    cout << "\n=== Different query (uncached) ===\n";
    auto r3 = service->fetchData("SELECT * FROM orders");

    cout << "\n";
    service->printStats();

    return 0;
}

