// Receiver: The object that performs the actual work
class TextEditor {
    string content;
    string clipboard;

public:
    void write(const string& text) {
        content += text;
    }

    void deleteRange(int start, int length) {
        if (start < (int)content.size()) {
            content.erase(start, min(length, (int)content.size() - start));
        }
    }

    void insert(int pos, const string& text) {
        if (pos <= (int)content.size()) {
            content.insert(pos, text);
        }
    }

    void copyToClipboard(const string& text) {
        clipboard = text;
    }

    string pasteFromClipboard() {
        return clipboard;
    }

    string getContent() const { return content; }
    int getLength() const { return content.size(); }
    string getRange(int start, int length) const {
        if (start >= (int)content.size()) return "";
        return content.substr(start, min(length, (int)content.size() - start));
    }
};

// Command Interface
class Command {
public:
    virtual ~Command() = default;
    virtual void execute() = 0;
    virtual void undo() = 0;
    virtual string getDescription() const = 0;
};

// Concrete Commands
class WriteCommand : public Command {
    TextEditor& editor;
    string text;
    int position;

public:
    WriteCommand(TextEditor& ed, const string& t) : editor(ed), text(t) {
        position = editor.getLength();
    }

    void execute() override {
        editor.write(text);
    }

    void undo() override {
        editor.deleteRange(position, text.size());
    }

    string getDescription() const override {
        return "Write '" + text + "'";
    }
};

class DeleteCommand : public Command {
    TextEditor& editor;
    int startPos;
    int length;
    string deletedText;
    bool executed = false;

public:
    DeleteCommand(TextEditor& ed, int start, int len) 
        : editor(ed), startPos(start), length(len) {}

    void execute() override {
        deletedText = editor.getRange(startPos, length);
        editor.deleteRange(startPos, length);
        executed = true;
    }

    void undo() override {
        if (executed) {
            editor.insert(startPos, deletedText);
        }
    }

    string getDescription() const override {
        return "Delete " + to_string(length) + " chars at pos " + to_string(startPos);
    }
};

class InsertCommand : public Command {
    TextEditor& editor;
    int position;
    string text;

public:
    InsertCommand(TextEditor& ed, int pos, const string& t) 
        : editor(ed), position(pos), text(t) {}

    void execute() override {
        editor.insert(position, text);
    }

    void undo() override {
        editor.deleteRange(position, text.size());
    }

    string getDescription() const override {
        return "Insert '" + text + "' at pos " + to_string(position);
    }
};

// Invoker: Manages command execution and history
class CommandManager {
    vector<unique_ptr<Command>> history;
    int currentIndex = -1;
    const size_t maxHistory = 100;

public:
    void executeCommand(unique_ptr<Command> cmd) {
        cmd->execute();

        // Remove any redo commands if we branch off
        if (currentIndex < (int)history.size() - 1) {
            history.erase(history.begin() + currentIndex + 1, history.end());
        }

        history.push_back(move(cmd));
        currentIndex++;

        // Limit history size
        if (history.size() > maxHistory) {
            history.erase(history.begin());
            currentIndex--;
        }
    }

    void undo() {
        if (currentIndex >= 0) {
            history[currentIndex]->undo();
            cout << "UNDO: " << history[currentIndex]->getDescription() << "\n";
            currentIndex--;
        } else {
            cout << "Nothing to undo\n";
        }
    }

    void redo() {
        if (currentIndex < (int)history.size() - 1) {
            currentIndex++;
            history[currentIndex]->execute();
            cout << "REDO: " << history[currentIndex]->getDescription() << "\n";
        } else {
            cout << "Nothing to redo\n";
        }
    }

    void printHistory() const {
        cout << "\n--- Command History ---\n";
        for (size_t i = 0; i < history.size(); i++) {
            cout << (i == (size_t)currentIndex ? " > " : "   ");
            cout << i + 1 << ". " << history[i]->getDescription() << "\n";
        }
        cout << "-----------------------\n";
    }
};

int main() {
    TextEditor editor;
    CommandManager manager;

    cout << "=== Executing Commands ===\n";
    manager.executeCommand(make_unique<WriteCommand>(editor, "Hello"));
    manager.executeCommand(make_unique<WriteCommand>(editor, " World"));
    manager.executeCommand(make_unique<InsertCommand>(editor, 5, ", Beautiful"));

    cout << "Content: '" << editor.getContent() << "'\n";

    manager.printHistory();

    cout << "\n=== Undo Operations ===\n";
    manager.undo();
    cout << "Content: '" << editor.getContent() << "'\n";

    manager.undo();
    cout << "Content: '" << editor.getContent() << "'\n";

    cout << "\n=== Redo Operation ===\n";
    manager.redo();
    cout << "Content: '" << editor.getContent() << "'\n";

    return 0;
}

