// Forward declarations
template<typename T>
class BinaryTree;

// Tree Node
template<typename T>
class TreeNode {
public:
    T value;
    unique_ptr<TreeNode<T>> left;
    unique_ptr<TreeNode<T>> right;
    TreeNode<T>* parent = nullptr;

    TreeNode(const T& val) : value(val) {}

    void setLeft(unique_ptr<TreeNode<T>> node) {
        left = move(node);
        if (left) left->parent = this;
    }

    void setRight(unique_ptr<TreeNode<T>> node) {
        right = move(node);
        if (right) right->parent = this;
    }
};

// Iterator for in-order traversal
template<typename T>
class InOrderIterator {
    TreeNode<T>* current;
    stack<TreeNode<T>*> nodeStack;

    void pushLeft(TreeNode<T>* node) {
        while (node) {
            nodeStack.push(node);
            node = node->left.get();
        }
    }

public:
    using iterator_category = input_iterator_tag;
    using value_type = T;
    using difference_type = ptrdiff_t;
    using pointer = T*;
    using reference = T&;

    InOrderIterator(TreeNode<T>* root) : current(nullptr) {
        pushLeft(root);
        if (!nodeStack.empty()) {
            current = nodeStack.top();
            nodeStack.pop();
        }
    }

    InOrderIterator() : current(nullptr) {}  // End iterator

    T& operator*() const { return current->value; }
    T* operator->() const { return &current->value; }

    InOrderIterator& operator++() {
        if (current->right) {
            pushLeft(current->right.get());
        }
        if (!nodeStack.empty()) {
            current = nodeStack.top();
            nodeStack.pop();
        } else {
            current = nullptr;
        }
        return *this;
    }

    InOrderIterator operator++(int) {
        InOrderIterator tmp = *this;
        ++(*this);
        return tmp;
    }

    bool operator==(const InOrderIterator& other) const {
        return current == other.current;
    }

    bool operator!=(const InOrderIterator& other) const {
        return !(*this == other);
    }
};

// Binary Tree with iterator support
template<typename T>
class BinaryTree {
    unique_ptr<TreeNode<T>> root;

public:
    void setRoot(unique_ptr<TreeNode<T>> node) {
        root = move(node);
    }

    TreeNode<T>* getRoot() const { return root.get(); }

    // Iterator interface
    InOrderIterator<T> begin() {
        return InOrderIterator<T>(root.get());
    }

    InOrderIterator<T> end() {
        return InOrderIterator<T>();
    }

    // Range-based for loop support
    InOrderIterator<T> begin() const {
        return InOrderIterator<T>(root.get());
    }

    InOrderIterator<T> end() const {
        return InOrderIterator<T>();
    }
};

int main() {
    BinaryTree<int> tree;

    // Build tree:
    //       4
    //      / \
    //     2   6
    //    / \  / \
    //   1  3 5  7

    auto root = make_unique<TreeNode<int>>(4);
    auto left = make_unique<TreeNode<int>>(2);
    auto right = make_unique<TreeNode<int>>(6);

    left->setLeft(make_unique<TreeNode<int>>(1));
    left->setRight(make_unique<TreeNode<int>>(3));

    right->setLeft(make_unique<TreeNode<int>>(5));
    right->setRight(make_unique<TreeNode<int>>(7));

    root->setLeft(move(left));
    root->setRight(move(right));
    tree.setRoot(move(root));

    cout << "In-order traversal: ";
    for (const auto& val : tree) {
        cout << val << " ";
    }
    cout << "\n";

    // Use with algorithms
    cout << "Sum: " << accumulate(tree.begin(), tree.end(), 0) << "\n";
    cout << "Max: " << *max_element(tree.begin(), tree.end()) << "\n";

