// Problem: Adding a new user requires updating all existing users
// Problem: Removing a user requires notifying all contacts
// Problem: Group messaging is extremely complex
// Problem: O(n²) connections in the system

#include <bits/stdc++.h>
using namespace std;

// Forward declaration
class ChatRoom;

// Colleague interface
class User {
protected:
    string name;
    ChatRoom* mediator = nullptr;

public:
    User(const string& n) : name(n) {}
    virtual ~User() = default;

    void setMediator(ChatRoom* room) { mediator = room; }
    string getName() const { return name; }

    virtual void send(const string& message) = 0;
    virtual void sendTo(const string& recipient, const string& message) = 0;
    virtual void receive(const string& message, const string& from) = 0;
    virtual void receivePrivate(const string& message, const string& from) = 0;
};

// Mediator Interface
class ChatRoom {
public:
    virtual ~ChatRoom() = default;
    virtual void registerUser(User* user) = 0;
    virtual void sendMessage(const string& message, User* sender) = 0;
    virtual void sendPrivateMessage(const string& message, User* sender, const string& recipient) = 0;
};

// Concrete Mediator
class ConcreteChatRoom : public ChatRoom {
    unordered_map<string, User*> users;
    vector<string> messageHistory;

public:
    void registerUser(User* user) override {
        users[user->getName()] = user;
        user->setMediator(this);
        cout << "[System] " << user->getName() << " joined the room\n";
    }

    void sendMessage(const string& message, User* sender) override {
        string fullMsg = "[" + sender->getName() + "]: " + message;
        messageHistory.push_back(fullMsg);

        for (auto& [name, user] : users) {
            if (user != sender) {
                user->receive(message, sender->getName());
            }
        }
    }

    void sendPrivateMessage(const string& message, User* sender, const string& recipient) override {
        auto it = users.find(recipient);
        if (it != users.end()) {
            it->second->receivePrivate(message, sender->getName());
        } else {
            sender->receivePrivate("User not found: " + recipient, "System");
        }
    }

