    bool cleared = false;

public:
    Aircraft(const string& cs, int alt, int x, int y)
        : callSign(cs), altitude(alt), positionX(x), positionY(y) {}

    void setATC(AirTrafficControl* control) { atc = control; }
    string getCallSign() const { return callSign; }
    int getAltitude() const { return altitude; }
    int getX() const { return positionX; }
    int getY() const { return positionY; }

    void requestLanding();
    void requestTakeoff();
    void requestAltitudeChange(int newAlt);
    void receiveInstruction(const string& instruction);

    void move(int dx, int dy) {
        positionX += dx;
        positionY += dy;
    }
};

// Mediator
class AirTrafficControl {
public:
    virtual ~AirTrafficControl() = default;
    virtual void registerAircraft(Aircraft* aircraft) = 0;
    virtual void requestLanding(Aircraft* aircraft) = 0;
    virtual void requestTakeoff(Aircraft* aircraft) = 0;
    virtual void requestAltitudeChange(Aircraft* aircraft, int newAlt) = 0;
    virtual void broadcast(const string& message, Aircraft* sender) = 0;
};

class ConcreteATC : public AirTrafficControl {
    vector<Aircraft*> aircrafts;
    bool runwayOccupied = false;
    Aircraft* activeRunway = nullptr;

    bool checkConflict(Aircraft* requester, int newAlt) {
        for (auto* ac : aircrafts) {
            if (ac != requester) {
                int dist = abs(ac->getX() - requester->getX()) + abs(ac->getY() - requester->getY());
                int altDiff = abs(ac->getAltitude() - newAlt);
                if (dist < 10 && altDiff < 1000) {
                    return true;  // Conflict detected
                }
            }
        }
        return false;
    }

public:
    void registerAircraft(Aircraft* aircraft) override {
        aircrafts.push_back(aircraft);
        aircraft->setATC(this);
        cout << "[ATC] Registered: " << aircraft->getCallSign() << "\n";
    }

    void requestLanding(Aircraft* aircraft) override {
        if (runwayOccupied) {
            aircraft->receiveInstruction("Runway occupied. Hold at current altitude.");
        } else {
            runwayOccupied = true;
            activeRunway = aircraft;
            aircraft->receiveInstruction("Cleared to land. Runway 09.");
            broadcast(aircraft->getCallSign() + " is landing. Maintain separation.", aircraft);
        }
    }

    void requestTakeoff(Aircraft* aircraft) override {
        if (runwayOccupied && activeRunway != aircraft) {
            aircraft->receiveInstruction("Runway occupied. Hold short.");
        } else {
            runwayOccupied = true;
            activeRunway = aircraft;
            aircraft->receiveInstruction("Cleared for takeoff. Runway 09.");
        }
    }

    void requestAltitudeChange(Aircraft* aircraft, int newAlt) override {
        if (checkConflict(aircraft, newAlt)) {
            aircraft->receiveInstruction("Altitude change DENIED. Traffic conflict detected.");
        } else {
            aircraft->receiveInstruction("Altitude change APPROVED. Climb/descend to " + to_string(newAlt));
        }
    }

    void broadcast(const string& message, Aircraft* sender) override {
        for (auto* ac : aircrafts) {
            if (ac != sender) {
                ac->receiveInstruction("[Broadcast] " + message);
            }
        }
    }

    void releaseRunway() {
        runwayOccupied = false;
        activeRunway = nullptr;
    }
};

void Aircraft::requestLanding() {
    cout << "[" << callSign << "] Requesting landing permission\n";
    if (atc) atc->requestLanding(this);
}

void Aircraft::requestTakeoff() {
    cout << "[" << callSign << "] Requesting takeoff clearance\n";
    if (atc) atc->requestTakeoff(this);
}

void Aircraft::requestAltitudeChange(int newAlt) {
    cout << "[" << callSign << "] Requesting altitude change to " << newAlt << "\n";
    if (atc) atc->requestAltitudeChange(this, newAlt);
}

void Aircraft::receiveInstruction(const string& instruction) {
    cout << "  [" << callSign << "] ATC: " << instruction << "\n";
}

