    ConcreteATC atc;

    Aircraft flight101("AA101", 10000, 0, 0);
    Aircraft flight202("BA202", 10500, 5, 5);
    Aircraft flight303("CA303", 5000, 50, 50);

    atc.registerAircraft(&flight101);
    atc.registerAircraft(&flight202);
    atc.registerAircraft(&flight303);

    cout << "\n=== Scenario 1: Landing Request ===\n";
    flight101.requestLanding();
    flight202.requestLanding();  // Should be denied - runway occupied

    cout << "\n=== Scenario 2: Altitude Change ===\n";
    flight101.requestAltitudeChange(11000);  // Conflict with BA202
    flight303.requestAltitudeChange(4000);   // No conflict

    return 0;
