// Memento: Opaque state container
class EditorMemento {
    friend class TextEditor;  // Only TextEditor can access internals

    string content;
    int cursorPosition;
    vector<string> selection;
    chrono::system_clock::time_point timestamp;

    EditorMemento(const string& c, int pos, const vector<string>& sel)
        : content(c), cursorPosition(pos), selection(sel),
          timestamp(chrono::system_clock::now()) {}

public:
    string getTimestamp() const {
        auto time = chrono::system_clock::to_time_t(timestamp);
        stringstream ss;
        ss << put_time(localtime(&time), "%Y-%m-%d %H:%M:%S");
        return ss.str();
    }
};

// Originator
class TextEditor {
    string content;
    int cursorPosition = 0;
    vector<string> selection;

public:
    void type(const string& text) {
        content.insert(cursorPosition, text);
        cursorPosition += text.size();
        selection.clear();
    }

    void deleteRange(int start, int length) {
        if (start < (int)content.size()) {
            content.erase(start, min(length, (int)content.size() - start));
            cursorPosition = start;
        }
    }

    void select(int start, int length) {
        selection.clear();
        if (start < (int)content.size()) {
            selection.push_back(content.substr(start, min(length, (int)content.size() - start)));
        }
    }

    void moveCursor(int pos) {
        cursorPosition = max(0, min(pos, (int)content.size()));
    }

    // Create memento (snapshot)
    unique_ptr<EditorMemento> save() {
        return unique_ptr<EditorMemento>(
            new EditorMemento(content, cursorPosition, selection)
        );
    }

    // Restore from memento
    void restore(const EditorMemento* memento) {
        content = memento->content;
        cursorPosition = memento->cursorPosition;
        selection = memento->selection;
    }

    void printState() const {
        cout << "Content: '" << content << "'\n";
        cout << "Cursor: " << cursorPosition << "\n";
        cout << "Selection: ";
        for (const auto& s : selection) cout << "'" << s << "' ";
        if (selection.empty()) cout << "(none)";
        cout << "\n";
    }

    string getContent() const { return content; }
};

// Caretaker: Manages memento history
class HistoryManager {
    vector<unique_ptr<EditorMemento>> history;
    int currentIndex = -1;
    const size_t maxHistory = 50;

public:
    void save(unique_ptr<EditorMemento> memento) {
        // Remove any redo states if we branch off
        if (currentIndex < (int)history.size() - 1) {
            history.erase(history.begin() + currentIndex + 1, history.end());
        }

        history.push_back(move(memento));
        currentIndex++;

        // Limit history
        if (history.size() > maxHistory) {
            history.erase(history.begin());
            currentIndex--;
        }
    }

    bool canUndo() const { return currentIndex >= 0; }
    bool canRedo() const { return currentIndex < (int)history.size() - 1; }

    const EditorMemento* undo() {
        if (canUndo()) {
            currentIndex--;
            return history[currentIndex + 1].get();
        }
        return nullptr;
    }

    const EditorMemento* redo() {
        if (canRedo()) {
            currentIndex++;
            return history[currentIndex].get();
        }
        return nullptr;
    }

    void printHistory() const {
        cout << "\n--- History ---\n";
        for (size_t i = 0; i < history.size(); i++) {
            cout << (i == (size_t)currentIndex ? " > " : "   ");
            cout << i + 1 << ". " << history[i]->getTimestamp() << "\n";
        }
        cout << "---------------\n";
    }
};

int main() {
    TextEditor editor;
    HistoryManager history;

    cout << "=== Initial State ===\n";
    editor.type("Hello");
    history.save(editor.save());
    editor.printState();

    cout << "\n=== After Typing ===\n";
    editor.type(" World");
    history.save(editor.save());
    editor.printState();

    cout << "\n=== After Selection ===\n";
    editor.select(6, 5);
    history.save(editor.save());
    editor.printState();

    history.printHistory();

    cout << "\n=== Undo ===\n";
    if (auto* memento = history.undo()) {
        editor.restore(memento);
        editor.printState();
    }

    cout << "\n=== Undo Again ===\n";
    if (auto* memento = history.undo()) {
        editor.restore(memento);
        editor.printState();
    }

    cout << "\n=== Redo ===\n";
    if (auto* memento = history.redo()) {
        editor.restore(memento);
        editor.printState();
    }

    return 0;
}

