class GameCharacter {
    string name;
    int health = 100;
    int mana = 50;
    int experience = 0;
    int level = 1;
    pair<int, int> position = {0, 0};
    vector<string> inventory;
    string currentMap = "Town";

public:
    GameCharacter(const string& n) : name(n) {}

    void takeDamage(int dmg) { health = max(0, health - dmg); }
    void heal(int amount) { health = min(100, health + amount); }
    void useMana(int amount) { mana = max(0, mana - amount); }
    void gainExp(int exp) {
        experience += exp;
        if (experience >= level * 100) {
            level++;
            experience = 0;
            health = 100;
            mana = 50;
            cout << "*** LEVEL UP! Now level " << level << " ***\n";
        }
    }
    void moveTo(int x, int y) { position = {x, y}; }
    void addItem(const string& item) { inventory.push_back(item); }
    void changeMap(const string& map) { currentMap = map; }

    unique_ptr<GameState> saveState() {
        return unique_ptr<GameState>(
            new GameState(health, mana, experience, level, position, inventory, currentMap)
        );
    }

    void loadState(const GameState* state) {
        health = state->health;
        mana = state->mana;
        experience = state->experience;
        level = state->level;
        position = state->position;
        inventory = state->inventory;
        currentMap = state->currentMap;
    }

    void printStatus() const {
        cout << "[" << name << "] Lv" << level << " | HP:" << health 
             << " | MP:" << mana << " | EXP:" << experience 
             << " | Pos:(" << position.first << "," << position.second << ")"
             << " | Map:" << currentMap << "\n";
        cout << "  Inventory: ";
        for (const auto& item : inventory) cout << item << " ";
        if (inventory.empty()) cout << "(empty)";
        cout << "\n";
    }
};

// Caretaker with named checkpoints
class SaveGameManager {
    unordered_map<string, unique_ptr<GameState>> checkpoints;

public:
    void saveCheckpoint(const string& name, unique_ptr<GameState> state) {
        checkpoints[name] = move(state);
        cout << "[Save] Checkpoint '" << name << "' created\n";
    }

    bool hasCheckpoint(const string& name) const {
        return checkpoints.find(name) != checkpoints.end();
    }

    const GameState* loadCheckpoint(const string& name) const {
        auto it = checkpoints.find(name);
        if (it != checkpoints.end()) {
            return it->second.get();
        }
        return nullptr;
    }

    void listCheckpoints() const {
        cout << "\n--- Saved Checkpoints ---\n";
        for (const auto& [name, state] : checkpoints) {
            cout << "  '" << name << "': " << state->getSummary() << "\n";
        }
        cout << "-------------------------\n";
    }
};

int main() {
    GameCharacter hero("Aragorn");
    SaveGameManager saveManager;

    cout << "=== Starting Adventure ===\n";
    hero.printStatus();

    // First checkpoint
    hero.moveTo(10, 20);
    hero.addItem("Sword");
    hero.addItem("Potion");
    saveManager.saveCheckpoint("Forest_Entry", hero.saveState());

    cout << "\n=== After Battle ===\n";
    hero.takeDamage(30);
    hero.useMana(20);
    hero.gainExp(150);  // Levels up
    hero.changeMap("Dungeon");
    hero.printStatus();

    // Second checkpoint
    saveManager.saveCheckpoint("Dungeon_Start", hero.saveState());

    cout << "\n=== Near Death Experience ===\n";
    hero.takeDamage(80);
