// Modern Observer using function callbacks
template<typename EventType>
class EventEmitter {
    unordered_map<string, vector<function<void(const EventType&)>>> listeners;

public:
    void on(const string& event, function<void(const EventType&)> callback) {
        listeners[event].push_back(callback);
    }

    void off(const string& event) {
        listeners.erase(event);
    }

    void emit(const string& event, const EventType& data) {
        auto it = listeners.find(event);
        if (it != listeners.end()) {
            for (const auto& callback : it->second) {
                callback(data);
            }
        }
    }

    size_t listenerCount(const string& event) const {
        auto it = listeners.find(event);
        return it != listeners.end() ? it->second.size() : 0;
    }
};

// Stock price event
struct StockPrice {
    string symbol;
    double price;
    double change;
    chrono::system_clock::time_point timestamp;
};

class StockMarket {
    EventEmitter<StockPrice> events;
    unordered_map<string, double> prices;

public:
    void subscribe(const string& symbol, function<void(const StockPrice&)> callback) {
        events.on(symbol, callback);
    }

    void updatePrice(const string& symbol, double newPrice) {
        double oldPrice = prices[symbol];
        prices[symbol] = newPrice;

        StockPrice event{symbol, newPrice, newPrice - oldPrice, chrono::system_clock::now()};
        events.emit(symbol, event);
    }

    double getPrice(const string& symbol) const {
        auto it = prices.find(symbol);
        return it != prices.end() ? it->second : 0.0;
    }
};

int main() {
    StockMarket market;

    // Multiple subscribers for AAPL
    market.subscribe("AAPL", [](const StockPrice& p) {
        cout << "[Trader A] " << p.symbol << " now at $" << p.price 
             << " (" << (p.change >= 0 ? "+" : "") << p.change << ")\n";
    });

    market.subscribe("AAPL", [](const StockPrice& p) {
        if (abs(p.change) > 5.0) {
            cout << "[Alert Bot] Significant price movement in " << p.symbol 
                 << ": " << p.change << "\n";
        }
    });

    market.subscribe("GOOGL", [](const StockPrice& p) {
        cout << "[Portfolio Manager] " << p.symbol << " updated to $" << p.price << "\n";
    });

    cout << "=== Market Updates ===\n";
    market.updatePrice("AAPL", 150.0);   // Initial
    market.updatePrice("AAPL", 155.0);   // +5
    market.updatePrice("AAPL", 162.0);   // +7 (triggers alert)
    market.updatePrice("GOOGL", 2800.0); // Different stock

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class ThreadSafeSubject {
    mutable shared_mutex mutex_;
    vector<weak_ptr<function<void(const string&)>>> observers;

public:
    void attach(shared_ptr<function<void(const string&)>> observer) {
        unique_lock lock(mutex_);
        observers.push_back(observer);
    }

    void notify(const string& data) {
        shared_lock lock(mutex_);
        // Clean up expired weak_ptrs and notify valid ones
        observers.erase(
            remove_if(observers.begin(), observers.end(),
                [&data](const weak_ptr<function<void(const string&)>>& wp) {
                    if (auto sp = wp.lock()) {
                        (*sp)(data);
                        return false;
                    }
                    return true;  // Remove expired
                }),
            observers.end()
        );
    }

    size_t observerCount() const {
        shared_lock lock(mutex_);
        return observers.size();
    }
};

int main() {
    ThreadSafeSubject subject;

    auto obs1 = make_shared<function<void(const string&)>>(
        [](const string& data) { cout << "Observer 1: " << data << "\n"; }
    );
    auto obs2 = make_shared<function<void(const string&)>>(
        [](const string& data) { cout << "Observer 2: " << data << "\n"; }
    );

    subject.attach(obs1);
    subject.attach(obs2);

    subject.notify("Hello from thread-safe subject!");

    // obs2 goes out of scope / is reset
    obs2.reset();
    subject.notify("After observer 2 expired");

    return 0;
}

