class Document {
    unique_ptr<DocumentState> state;
    string content;
    string title;
    vector<string> history;

public:
    Document(const string& t) : title(t) {
        // Initial state set externally
    }

    void setState(unique_ptr<DocumentState> newState) {
        if (state) {
            history.push_back("Transition: " + state->getName() + " -> " + newState->getName());
        }
        state = move(newState);
    }

    void edit(const string& text) { state->edit(this, text); }
    void review() { state->review(this); }
    void approve() { state->approve(this); }
    void reject(const string& reason) { state->reject(this, reason); }
    void publish() { state->publish(this); }
    void archive() { state->archive(this); }

    void setContent(const string& c) { content = c; }
    string getContent() const { return content; }
    string getTitle() const { return title; }

    void printState() const {
        cout << "Document: '" << title << "' | State: " << state->getName() 
             << " | Content: '" << content << "'\n";
    }

    void printHistory() const {
        cout << "\n--- Transition History ---\n";
        for (const auto& h : history) cout << "  " << h << "\n";
        cout << "--------------------------\n";
    }
};

// Concrete States
class DraftState : public DocumentState {
public:
    string getName() const override { return "Draft"; }

    void edit(Document* doc, const string& text) override {
        doc->setContent(text);
        cout << "[Draft] Content updated\n";
    }

    void review(Document* doc) override {
        cout << "[Draft] Submitting for review...\n";
        doc->setState(make_unique<ReviewState>());
    }

    void approve(Document* doc) override {
        cout << "[Draft] Cannot approve - must be in review first\n";
    }

    void reject(Document* doc, const string& reason) override {
        cout << "[Draft] Cannot reject - not under review\n";
    }

    void publish(Document* doc) override {
        cout << "[Draft] Cannot publish - must be approved first\n";
    }

    void archive(Document* doc) override {
        cout << "[Draft] Archiving draft...\n";
        doc->setState(make_unique<ArchivedState>());
    }
};

class ReviewState : public DocumentState {
    int reviewCount = 0;

public:
    string getName() const override { return "Under Review"; }

    void edit(Document* doc, const string& text) override {
        cout << "[Review] Cannot edit while under review\n";
    }

    void review(Document* doc) override {
        reviewCount++;
        cout << "[Review] Review round " << reviewCount << " completed\n";
    }

    void approve(Document* doc) override {
        cout << "[Review] Document approved!\n";
        doc->setState(make_unique<ApprovedState>());
    }

    void reject(Document* doc, const string& reason) override {
        cout << "[Review] Rejected: " << reason << "\n";
        doc->setState(make_unique<RejectedState>());
    }

    void publish(Document* doc) override {
        cout << "[Review] Cannot publish - approval pending\n";
    }

    void archive(Document* doc) override {
        cout << "[Review] Cannot archive during review\n";
    }
};

class ApprovedState : public DocumentState {
public:
    string getName() const override { return "Approved"; }

    void edit(Document* doc, const string& text) override {
        cout << "[Approved] Cannot edit - document is finalized\n";
    }

    void review(Document* doc) override {
        cout << "[Approved] Already approved\n";
    }

    void approve(Document* doc) override {
        cout << "[Approved] Already approved\n";
    }

    void reject(Document* doc, const string& reason) override {
        cout << "[Approved] Cannot reject after approval\n";
    }

    void publish(Document* doc) override {
        cout << "[Approved] Publishing document...\n";
        doc->setState(make_unique<PublishedState>());
    }

    void archive(Document* doc) override {
        cout << "[Approved] Archiving...\n";
        doc->setState(make_unique<ArchivedState>());
    }
};

class PublishedState : public DocumentState {
public:
    string getName() const override { return "Published"; }

    void edit(Document* doc, const string& text) override {
        cout << "[Published] Creating new draft version...\n";
        doc->setState(make_unique<DraftState>());
        doc->edit(text);
    }

    void review(Document* doc) override {
        cout << "[Published] Already published\n";
    }

    void approve(Document* doc) override {
        cout << "[Published] Already approved and published\n";
    }

    void reject(Document* doc, const string& reason) override {
        cout << "[Published] Cannot reject published document\n";
    }

    void publish(Document* doc) override {
        cout << "[Published] Already published\n";
    }

    void archive(Document* doc) override {
        cout << "[Published] Retiring to archive...\n";
        doc->setState(make_unique<ArchivedState>());
    }
};

class RejectedState : public DocumentState {
    string rejectionReason;

public:
    string getName() const override { return "Rejected"; }

    void edit(Document* doc, const string& text) override {
        cout << "[Rejected] Revising based on feedback...\n";
        doc->setState(make_unique<DraftState>());
        doc->edit(text);
    }

    void review(Document* doc) override {
        cout << "[Rejected] Must edit before resubmitting\n";
    }

    void approve(Document* doc) override {
        cout << "[Rejected] Cannot approve rejected document\n";
    }

    void reject(Document* doc, const string& reason) override {
        cout << "[Rejected] Already rejected\n";
    }

    void publish(Document* doc) override {
        cout << "[Rejected] Cannot publish rejected document\n";
    }

    void archive(Document* doc) override {
        cout << "[Rejected] Archiving rejected draft...\n";
        doc->setState(make_unique<ArchivedState>());
    }
};

class ArchivedState : public DocumentState {
public:
    string getName() const override { return "Archived"; }

    void edit(Document* doc, const string& text) override {
        cout << "[Archived] Cannot edit archived document\n";
    }

    void review(Document* doc) override {
        cout << "[Archived] Cannot review archived document\n";
    }

    void approve(Document* doc) override {
        cout << "[Archived] Cannot approve archived document\n";
    }

    void reject(Document* doc, const string& reason) override {
        cout << "[Archived] Cannot reject archived document\n";
    }

    void publish(Document* doc) override {
        cout << "[Archived] Cannot publish archived document\n";
    }

    void archive(Document* doc) override {
        cout << "[Archived] Already archived\n";
    }
};

int main() {
    Document doc("Project Proposal");
    doc.setState(make_unique<DraftState>());

    cout << "=== Workflow Demo ===\n\n";

    doc.printState();
    doc.edit("Initial draft content");

    cout << "\n--- Submit for Review ---\n";
    doc.review();
    doc.printState();

    cout << "\n--- Review Round ---\n";
    doc.review();

    cout << "\n--- Approve ---\n";
    doc.approve();
    doc.printState();

    cout << "\n--- Try Invalid Actions ---\n";
    doc.edit("Sneaky edit");  // Should fail
    doc.reject("Just kidding");  // Should fail

    cout << "\n--- Publish ---\n";
    doc.publish();
    doc.printState();

    cout << "\n--- Create New Version ---\n";
    doc.edit("Version 2.0 content");
    doc.printState();

    doc.printHistory();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class Player;

// State Interface
class PlayerState {
public:
    virtual ~PlayerState() = default;
    virtual void enter(Player* player) = 0;
    virtual void exit(Player* player) = 0;
    virtual void update(Player* player, float deltaTime) = 0;
    virtual void handleInput(Player* player, const string& input) = 0;
    virtual string getName() const = 0;
};

class Player {
    unique_ptr<PlayerState> state;
    string name;
    int health = 100;
    float x = 0, y = 0;
    float velocityX = 0, velocityY = 0;

public:
    Player(const string& n) : name(n) {}

    void setState(unique_ptr<PlayerState> newState) {
        if (state) state->exit(this);
        state = move(newState);
        if (state) state->enter(this);
    }

    void update(float deltaTime) {
        if (state) state->update(this, deltaTime);
    }

    void handleInput(const string& input) {
        if (state) state->handleInput(this, input);
    }

    void takeDamage(int dmg) { health = max(0, health - dmg); }
    void heal(int amount) { health = min(100, health + amount); }
    void move(float dx, float dy) { x += dx; y += dy; }
    void setVelocity(float vx, float vy) { velocityX = vx; velocityY = vy; }

    int getHealth() const { return health; }
    string getName() const { return name; }
    string getStateName() const { return state ? state->getName() : "None"; }

    void printStatus() const {
        cout << "[" << name << "] HP:" << health << " Pos:(" << x << "," << y 
             << ") State:" << getStateName() << "\n";
    }
};

// Concrete States
class IdleState : public PlayerState {
public:
    string getName() const override { return "Idle"; }

    void enter(Player* player) override {
        cout << "[" << player->getName() << "] Entering Idle state\n";
        player->setVelocity(0, 0);
    }

    void exit(Player* player) override {
        cout << "[" << player->getName() << "] Leaving Idle state\n";
    }

    void update(Player* player, float deltaTime) override {
        // Regenerate health slowly while idle
        static float healTimer = 0;
        healTimer += deltaTime;
        if (healTimer > 2.0f) {
            player->heal(1);
            healTimer = 0;
        }
    }

    void handleInput(Player* player, const string& input) override {
        if (input == "move") {
            player->setState(make_unique<WalkingState>());
        } else if (input == "attack") {
            player->setState(make_unique<AttackingState>());
        } else if (input == "jump") {
            player->setState(make_unique<JumpingState>());
        }
    }
};

class WalkingState : public PlayerState {
    float walkSpeed = 5.0f;

public:
    string getName() const override { return "Walking"; }

    void enter(Player* player) override {
        cout << "[" << player->getName() << "] Started walking\n";
    }

    void exit(Player* player) override {
        cout << "[" << player->getName() << "] Stopped walking\n";
    }

    void update(Player* player, float deltaTime) override {
        player->move(velocityX * deltaTime, velocityY * deltaTime);
    }

    void handleInput(Player* player, const string& input) override {
        if (input == "stop") {
            player->setState(make_unique<IdleState>());
        } else if (input == "run") {
            player->setState(make_unique<RunningState>());
        } else if (input == "attack") {
            player->setState(make_unique<AttackingState>());
        }
    }

    float velocityX = 1.0f, velocityY = 0.0f;
};

class RunningState : public PlayerState {
public:
    string getName() const override { return "Running"; }

    void enter(Player* player) override {
        cout << "[" << player->getName() << "] Started running!\n";
    }

    void exit(Player* player) override {
        cout << "[" << player->getName() << "] Stopped running\n";
    }

    void update(Player* player, float deltaTime) override {
        player->move(10.0f * deltaTime, 0);
    }

    void handleInput(Player* player, const string& input) override {
        if (input == "stop") {
            player->setState(make_unique<IdleState>());
        } else if (input == "walk") {
            player->setState(make_unique<WalkingState>());
        }
    }
};

class AttackingState : public PlayerState {
    float attackTimer = 0;
    const float attackDuration = 0.5f;

public:
    string getName() const override { return "Attacking"; }

    void enter(Player* player) override {
        cout << "[" << player->getName() << "] Attack!\n";
        attackTimer = 0;
    }

    void exit(Player* player) override {}

    void update(Player* player, float deltaTime) override {
        attackTimer += deltaTime;
        if (attackTimer >= attackDuration) {
            cout << "[" << player->getName() << "] Attack complete\n";
            player->setState(make_unique<IdleState>());
        }
    }

    void handleInput(Player* player, const string& input) override {
        // Cannot change state during attack
        cout << "[" << player->getName() << "] Busy attacking!\n";
    }
};

class JumpingState : public PlayerState {
    float jumpTimer = 0;
    const float jumpDuration = 1.0f;

public:
    string getName() const override { return "Jumping"; }

    void enter(Player* player) override {
        cout << "[" << player->getName() << "] Jump!\n";
        jumpTimer = 0;
    }

    void exit(Player* player) override {
        cout << "[" << player->getName() << "] Landed\n";
    }

    void update(Player* player, float deltaTime) override {
        jumpTimer += deltaTime;
        // Parabolic arc
        float height = 10.0f * jumpTimer - 5.0f * jumpTimer * jumpTimer;
        if (height < 0) height = 0;

        if (jumpTimer >= jumpDuration) {
            player->setState(make_unique<IdleState>());
        }
    }

    void handleInput(Player* player, const string& input) override {
        // Limited actions while jumping
        if (input == "attack") {
            cout << "[" << player->getName() << "] Air attack!\n";
        }
    }
};

class DeadState : public PlayerState {
public:
    string getName() const override { return "Dead"; }

    void enter(Player* player) override {
        cout << "[" << player->getName() << "] You died!\n";
    }

    void exit(Player* player) override {
        cout << "[" << player->getName() << "] Respawned!\n";
    }

    void update(Player* player, float deltaTime) override {
        // Dead players don't update
    }

    void handleInput(Player* player, const string& input) override {
        if (input == "respawn") {
            player->setState(make_unique<IdleState>());
        }
    }
};

int main() {
    Player hero("Hero");
    hero.setState(make_unique<IdleState>());

    cout << "=== Gameplay Demo ===\n\n";

    hero.printStatus();

    cout << "\n--- Walk ---\n";
    hero.handleInput("move");
    hero.update(0.1f);
    hero.printStatus();

    cout << "\n--- Attack ---\n";
    hero.handleInput("attack");
    hero.update(0.3f);
    hero.printStatus();
    hero.handleInput("move");  // Should be ignored
    hero.update(0.3f);  // Attack completes
    hero.printStatus();

    cout << "\n--- Jump ---\n";
    hero.handleInput("jump");
    hero.update(0.5f);
    hero.printStatus();
    hero.update(0.6f);  // Landing
    hero.printStatus();

    cout << "\n--- Take Damage ---\n";
    hero.takeDamage(100);
    if (hero.getHealth() <= 0) {
        hero.setState(make_unique<DeadState>());
    }
    hero.printStatus();

    cout << "\n--- Respawn ---\n";
    hero.handleInput("respawn");
    hero.printStatus();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// State machine using transition table - more declarative approach
enum class State { IDLE, WALKING, RUNNING, ATTACKING, JUMPING, DEAD };
enum class Event { MOVE, STOP, RUN, ATTACK, JUMP, DAMAGE, RESPAWN };

class StateMachine {
    State currentState = State::IDLE;

    // Transition table: currentState + event -> newState (nullopt = no transition)
    using TransitionTable = map<pair<State, Event>, State>;
    TransitionTable transitions = {
        {{State::IDLE, Event::MOVE}, State::WALKING},
        {{State::IDLE, Event::ATTACK}, State::ATTACKING},
        {{State::IDLE, Event::JUMP}, State::JUMPING},
        {{State::WALKING, Event::STOP}, State::IDLE},
        {{State::WALKING, Event::RUN}, State::RUNNING},
        {{State::WALKING, Event::ATTACK}, State::ATTACKING},
        {{State::RUNNING, Event::STOP}, State::IDLE},
        {{State::RUNNING, Event::MOVE}, State::WALKING},
        {{State::ATTACKING, Event::STOP}, State::IDLE},
        {{State::JUMPING, Event::STOP}, State::IDLE},
        {{State::IDLE, Event::DAMAGE}, State::DEAD},
        {{State::WALKING, Event::DAMAGE}, State::DEAD},
        {{State::RUNNING, Event::DAMAGE}, State::DEAD},
        {{State::DEAD, Event::RESPAWN}, State::IDLE},
    };

    // Entry/exit actions
    function<void(State)> onEnter;
    function<void(State)> onExit;

public:
    void setCallbacks(function<void(State)> enter, function<void(State)> exit) {
        onEnter = enter;
        onExit = exit;
    }

    bool handleEvent(Event event) {
        auto key = make_pair(currentState, event);
        auto it = transitions.find(key);

        if (it != transitions.end()) {
            State oldState = currentState;
            currentState = it->second;

            if (onExit) onExit(oldState);
            if (onEnter) onEnter(currentState);

            return true;
        }
        return false;  // No valid transition
    }

    State getState() const { return currentState; }

    string getStateName() const {
        switch (currentState) {
            case State::IDLE: return "Idle";
            case State::WALKING: return "Walking";
            case State::RUNNING: return "Running";
            case State::ATTACKING: return "Attacking";
            case State::JUMPING: return "Jumping";
            case State::DEAD: return "Dead";
        }
        return "Unknown";
    }

    void printTransitions() const {
        cout << "Valid transitions from " << getStateName() << ":\n";
        for (const auto& [key, state] : transitions) {
            if (key.first == currentState) {
                cout << "  -> ";
                switch (key.second) {
                    case Event::MOVE: cout << "MOVE"; break;
                    case Event::STOP: cout << "STOP"; break;
                    case Event::RUN: cout << "RUN"; break;
                    case Event::ATTACK: cout << "ATTACK"; break;
                    case Event::JUMP: cout << "JUMP"; break;
                    case Event::DAMAGE: cout << "DAMAGE"; break;
                    case Event::RESPAWN: cout << "RESPAWN"; break;
                }
                cout << " -> " << getStateName() << "\n";
            }
        }
    }
};

int main() {
    StateMachine fsm;

    fsm.setCallbacks(
        [](State s) { cout << "[FSM] Entered state\n"; },
        [](State s) { cout << "[FSM] Exited state\n"; }
    );

    cout << "=== State Machine Demo ===\n";
    cout << "Initial: " << fsm.getStateName() << "\n";

    cout << "\n--- Valid Transitions ---\n";
    fsm.printTransitions();

    cout << "\n--- Events ---\n";
    cout << "MOVE: " << (fsm.handleEvent(Event::MOVE) ? "Success" : "Failed") << "\n";
    cout << "State: " << fsm.getStateName() << "\n";

    cout << "JUMP: " << (fsm.handleEvent(Event::JUMP) ? "Success" : "Failed") << "\n";
    cout << "State: " << fsm.getStateName() << "\n";

    cout << "RUN: " << (fsm.handleEvent(Event::RUN) ? "Success" : "Failed") << "\n";
    cout << "State: " << fsm.getStateName() << "\n";

    cout << "DAMAGE: " << (fsm.handleEvent(Event::DAMAGE) ? "Success" : "Failed") << "\n";
    cout << "State: " << fsm.getStateName() << "\n";

    cout << "MOVE (while dead): " << (fsm.handleEvent(Event::MOVE) ? "Success" : "Failed") << "\n";

    cout << "RESPAWN: " << (fsm.handleEvent(Event::RESPAWN) ? "Success" : "Failed") << "\n";
    cout << "State: " << fsm.getStateName() << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Strategy Interface
class SortStrategy {
public:
    virtual ~SortStrategy() = default;
    virtual void sort(vector<int>& data) = 0;
    virtual string getName() const = 0;
};

// Concrete Strategies
class QuickSort : public SortStrategy {
    void quickSort(vector<int>& arr, int low, int high) {
        if (low < high) {
            int pi = partition(arr, low, high);
            quickSort(arr, low, pi - 1);
            quickSort(arr, pi + 1, high);
        }
    }

    int partition(vector<int>& arr, int low, int high) {
        int pivot = arr[high];
        int i = low - 1;
        for (int j = low; j < high; j++) {
            if (arr[j] < pivot) {
                i++;
                swap(arr[i], arr[j]);
            }
        }
        swap(arr[i + 1], arr[high]);
        return i + 1;
    }

public:
    void sort(vector<int>& data) override {
        quickSort(data, 0, data.size() - 1);
    }

    string getName() const override { return "QuickSort"; }
};

class MergeSort : public SortStrategy {
    void merge(vector<int>& arr, int left, int mid, int right) {
        int n1 = mid - left + 1;
        int n2 = right - mid;
        vector<int> L(n1), R(n2);

        for (int i = 0; i < n1; i++) L[i] = arr[left + i];
        for (int i = 0; i < n2; i++) R[i] = arr[mid + 1 + i];

        int i = 0, j = 0, k = left;
        while (i < n1 && j < n2) {
            if (L[i] <= R[j]) arr[k++] = L[i++];
            else arr[k++] = R[j++];
        }
        while (i < n1) arr[k++] = L[i++];
        while (j < n2) arr[k++] = R[j++];
    }

    void mergeSort(vector<int>& arr, int left, int right) {
        if (left < right) {
            int mid = left + (right - left) / 2;
            mergeSort(arr, left, mid);
            mergeSort(arr, mid + 1, right);
            merge(arr, left, mid, right);
        }
    }

public:
    void sort(vector<int>& data) override {
        mergeSort(data, 0, data.size() - 1);
    }

    string getName() const override { return "MergeSort"; }
};

class HeapSort : public SortStrategy {
    void heapify(vector<int>& arr, int n, int i) {
        int largest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;

        if (left < n && arr[left] > arr[largest]) largest = left;
        if (right < n && arr[right] > arr[largest]) largest = right;

        if (largest != i) {
            swap(arr[i], arr[largest]);
            heapify(arr, n, largest);
        }
    }

public:
    void sort(vector<int>& data) override {
        int n = data.size();
        for (int i = n / 2 - 1; i >= 0; i--)
            heapify(data, n, i);
        for (int i = n - 1; i > 0; i--) {
            swap(data[0], data[i]);
            heapify(data, i, 0);
        }
    }

    string getName() const override { return "HeapSort"; }
};

class BubbleSort : public SortStrategy {
public:
    void sort(vector<int>& data) override {
        int n = data.size();
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - i - 1; j++) {
                if (data[j] > data[j + 1]) {
                    swap(data[j], data[j + 1]);
                }
            }
        }
    }

    string getName() const override { return "BubbleSort"; }
};

// Context
class Sorter {
    unique_ptr<SortStrategy> strategy;

public:
    void setStrategy(unique_ptr<SortStrategy> strat) {
        strategy = move(strat);
    }

    void sort(vector<int>& data) {
        if (!strategy) {
            throw runtime_error("No sorting strategy set");
        }

        auto start = chrono::high_resolution_clock::now();
        strategy->sort(data);
        auto end = chrono::high_resolution_clock::now();

        auto duration = chrono::duration_cast<chrono::microseconds>(end - start);
        cout << strategy->getName() << " completed in " << duration.count() << " μs\n";
    }

    string getCurrentStrategy() const {
        return strategy ? strategy->getName() : "None";
    }
};

// Strategy with runtime selection based on data characteristics
class AdaptiveSorter {
public:
    static void sort(vector<int>& data) {
        unique_ptr<SortStrategy> strategy;

        if (data.size() <= 10) {
            strategy = make_unique<BubbleSort>();
        } else if (data.size() <= 1000) {
            strategy = make_unique<QuickSort>();
        } else {
            strategy = make_unique<MergeSort>();
        }

        cout << "AdaptiveSorter chose: " << strategy->getName() 
             << " for n=" << data.size() << "\n";
        strategy->sort(data);
    }
};

int main() {
    Sorter sorter;

    // Test data
    vector<int> data1 = {64, 34, 25, 12, 22, 11, 90};
    vector<int> data2 = {64, 34, 25, 12, 22, 11, 90};
    vector<int> data3 = {64, 34, 25, 12, 22, 11, 90};

    cout << "=== Strategy Pattern Demo ===\n\n";

    cout << "--- QuickSort ---\n";
    sorter.setStrategy(make_unique<QuickSort>());
    sorter.sort(data1);

    cout << "\n--- MergeSort ---\n";
    sorter.setStrategy(make_unique<MergeSort>());
    sorter.sort(data2);

    cout << "\n--- HeapSort ---\n";
    sorter.setStrategy(make_unique<HeapSort>());
    sorter.sort(data3);

    cout << "\n--- Adaptive Sorting ---\n";
    vector<int> small = {5, 2, 8};
    vector<int> medium(500);
    generate(medium.begin(), medium.end(), rand);

    AdaptiveSorter::sort(small);
    AdaptiveSorter::sort(medium);

