// Modern approach using std::function for lightweight strategies
class PaymentProcessor {
    function<bool(double, const string&)> paymentStrategy;
    string strategyName;

public:
    void setStrategy(const string& name, function<bool(double, const string&)> strategy) {
        strategyName = name;
        paymentStrategy = strategy;
    }

    bool processPayment(double amount, const string& currency) {
        cout << "Processing $" << amount << " " << currency 
             << " using " << strategyName << "...\n";
        if (paymentStrategy) {
            return paymentStrategy(amount, currency);
        }
        return false;
    }
};

class ShoppingCart {
    vector<pair<string, double>> items;
    PaymentProcessor payment;

public:
    void addItem(const string& name, double price) {
        items.push_back({name, price});
    }

    double getTotal() const {
        double total = 0;
        for (const auto& item : items) total += item.second;
        return total;
    }

    void setPaymentStrategy(const string& name, function<bool(double, const string&)> strategy) {
        payment.setStrategy(name, strategy);
    }

    bool checkout(const string& currency = "USD") {
        double total = getTotal();
        cout << "\n=== Checkout ===\n";
        cout << "Items:\n";
        for (const auto& item : items) {
            cout << "  " << item.first << ": $" << item.second << "\n";
        }
        cout << "Total: $" << total << "\n";

        return payment.processPayment(total, currency);
    }
};

