// Logging policies
struct ConsoleLogger {
    static void log(const string& msg) {
        cout << "[CONSOLE] " << msg << "\n";
    }
};

struct FileLogger {
    static void log(const string& msg) {
        // In real code, would write to file
        cout << "[FILE] " << msg << "\n";
    }
};

struct NullLogger {
    static void log(const string& msg) {
        // No-op for release builds
    }
};

// Validation policies
struct StrictValidator {
    static bool validateEmail(const string& email) {
        return email.find('@') != string::npos && 
               email.find('.') != string::npos &&
               email.length() >= 5;
    }

    static bool validatePassword(const string& pwd) {
        return pwd.length() >= 12 &&
               any_of(pwd.begin(), pwd.end(), ::isupper) &&
               any_of(pwd.begin(), pwd.end(), ::islower) &&
               any_of(pwd.begin(), pwd.end(), ::isdigit) &&
               any_of(pwd.begin(), pwd.end(), ::ispunct);
    }
};

struct LenientValidator {
    static bool validateEmail(const string& email) {
        return email.find('@') != string::npos;
    }

    static bool validatePassword(const string& pwd) {
        return pwd.length() >= 6;
    }
};

// Context with compile-time policies
template<typename Logger, typename Validator>
class UserService {
public:
    bool registerUser(const string& email, const string& password) {
        Logger::log("Attempting registration for: " + email);

        if (!Validator::validateEmail(email)) {
            Logger::log("Registration failed: Invalid email");
            return false;
        }

        if (!Validator::validatePassword(password)) {
            Logger::log("Registration failed: Weak password");
            return false;
        }

        Logger::log("Registration successful");
        return true;
    }

    void authenticate(const string& email, const string& password) {
        Logger::log("Authenticating: " + email);
        // Authentication logic...
    }
};

int main() {
    cout << "=== Strict Service with Console Logging ===\n";
    UserService<ConsoleLogger, StrictValidator> strictService;
    strictService.registerUser("user@example.com", "Weak1");  // Should fail
    strictService.registerUser("user@example.com", "Str0ng!Passw0rd");  // Should pass

    cout << "\n=== Lenient Service with File Logging ===\n";
    UserService<FileLogger, LenientValidator> lenientService;
    lenientService.registerUser("user@example", "123456");  // Should pass (lenient)

    cout << "\n=== Production Service with Null Logging ===\n";
    UserService<NullLogger, StrictValidator> prodService;
    prodService.registerUser("user@example.com", "Str0ng!Passw0rd");
    // No log output - optimized for production

    return 0;
}

