// Abstract Class with Template Method
class DataMiner {
public:
    // Template Method - defines the algorithm skeleton
    void mine(const string& path) {
        auto file = openFile(path);
        auto rawData = extractData(file);
        auto data = parseData(rawData);
        auto analysis = analyzeData(data);
        sendReport(analysis);
        closeFile(file);
        hook();  // Optional extension point
    }

    virtual ~DataMiner() = default;

protected:
    // Steps with default implementations (can be overridden)
    virtual void* openFile(const string& path) {
        cout << "[Base] Opening file: " << path << "\n";
        return nullptr;
    }

    virtual void closeFile(void* file) {
        cout << "[Base] Closing file\n";
    }

    // Steps that MUST be implemented by subclasses
    virtual string extractData(void* file) = 0;
    virtual vector<map<string, string>> parseData(const string& rawData) = 0;

    // Step with default implementation
    virtual string analyzeData(const vector<map<string, string>>& data) {
        cout << "[Base] Performing standard analysis on " << data.size() << " records\n";
        return "Standard Analysis: " + to_string(data.size()) + " records processed";
    }

    virtual void sendReport(const string& analysis) {
        cout << "[Base] Sending report: " << analysis << "\n";
    }

    // Hook - optional override
    virtual void hook() {
        cout << "[Base] Hook executed (default)\n";
    }
};

// Concrete Class: PDF Data Mining
class PDFDataMiner : public DataMiner {
protected:
    string extractData(void* file) override {
        cout << "[PDF] Extracting text from PDF structure\n";
        return "PDF raw content with tables and text blocks";
    }

    vector<map<string, string>> parseData(const string& rawData) override {
        cout << "[PDF] Parsing PDF-specific markup\n";
        return {
            {{"type", "pdf_table"}, {"rows", "10"}},
            {{"type", "pdf_text"}, {"pages", "5"}}
        };
    }

    void hook() override {
        cout << "[PDF] Cleaning up PDF resources\n";
    }
};

// Concrete Class: CSV Data Mining
class CSVDataMiner : public DataMiner {
    char delimiter;

public:
    CSVDataMiner(char delim = ',') : delimiter(delim) {}

protected:
    string extractData(void* file) override {
        cout << "[CSV] Reading comma-separated values\n";
        return "name,age,city\nAlice,30,NYC\nBob,25,LA";
    }

    vector<map<string, string>> parseData(const string& rawData) override {
        cout << "[CSV] Parsing with delimiter '" << delimiter << "'\n";
        vector<map<string, string>> result;
        stringstream ss(rawData);
        string line;

        // Skip header
        getline(ss, line);

        while (getline(ss, line)) {
            stringstream lineStream(line);
            string name, age, city;
            getline(lineStream, name, delimiter);
            getline(lineStream, age, delimiter);
            getline(lineStream, city, delimiter);
            result.push_back({{"name", name}, {"age", age}, {"city", city}});
        }
        return result;
    }

    string analyzeData(const vector<map<string, string>>& data) override {
        cout << "[CSV] Performing CSV-specific statistical analysis\n";
        int totalAge = 0;
        for (const auto& row : data) {
            totalAge += stoi(row.at("age"));
        }
        double avgAge = data.empty() ? 0 : (double)totalAge / data.size();
        return "CSV Analysis: " + to_string(data.size()) + " rows, avg age = " + to_string(avgAge);
    }
};

