// CRTP: Compile-time polymorphism for zero-overhead template method

template<typename Derived>
class GameLoop {
public:
    void run() {
        static_cast<Derived*>(this)->initialize();

        while (!static_cast<Derived*>(this)->shouldQuit()) {
            static_cast<Derived*>(this)->processInput();
            static_cast<Derived*>(this)->update();
            static_cast<Derived*>(this)->render();
            static_cast<Derived*>(this)->frameDelay();
        }

        static_cast<Derived*>(this)->cleanup();
    }

protected:
    // Default implementations
    void initialize() { cout << "[Base] Initializing engine\n"; }
    void cleanup() { cout << "[Base] Cleaning up\n"; }
    void frameDelay() { this_thread::sleep_for(chrono::milliseconds(16)); }  // ~60 FPS
    bool shouldQuit() { return false; }
};

class PlatformerGame : public GameLoop<PlatformerGame> {
