    }

    void processInput() {
        // Simulated input
        if (frameCount == 3) quit = true;
    }

    void update() {
        playerX += 2;
        cout << "[Platformer] Player at (" << playerX << "," << playerY << ")\n";
    }

    void render() {
        cout << "[Platformer] Rendering frame " << ++frameCount << "\n";
    }

    bool shouldQuit() { return quit; }

    void cleanup() {
        cout << "[Platformer] Saving progress, unloading assets\n";
    }
};

