// Template method for unit test framework
class TestCase {
    string testName;
    bool passed = true;
    string failureMessage;

public:
    TestCase(const string& name) : testName(name) {}
    virtual ~TestCase() = default;

    void run() {
        cout << "\n[TEST] " << testName << "\n";
        try {
            setUp();
            executeTest();
            tearDown();
            cout << "[PASS] " << testName << "\n";
        } catch (const exception& e) {
            passed = false;
            failureMessage = e.what();
            tearDown();
            cout << "[FAIL] " << testName << ": " << e.what() << "\n";
        }
    }

    bool didPass() const { return passed; }

protected:
    virtual void setUp() {
        cout << "  [SETUP] Default setup\n";
    }

    virtual void executeTest() = 0;

    virtual void tearDown() {
        cout << "  [TEARDOWN] Default cleanup\n";
    }

    void assertTrue(bool condition, const string& message) {
        if (!condition) {
            throw runtime_error("Assertion failed: " + message);
        }
    }

    template<typename T>
    void assertEqual(const T& expected, const T& actual, const string& message = "") {
        if (expected != actual) {
            stringstream ss;
            ss << "Expected: " << expected << ", Actual: " << actual;
            if (!message.empty()) ss << " (" << message << ")";
            throw runtime_error(ss.str());
        }
    }
};

// Concrete tests
class StackTest : public TestCase {
    stack<int> testStack;

public:
    StackTest() : TestCase("Stack Operations") {}

protected:
    void setUp() override {
        cout << "  [SETUP] Creating fresh stack\n";
        testStack = stack<int>();
    }

    void executeTest() override {
        assertTrue(testStack.empty(), "Stack should be empty initially");

        testStack.push(10);
        testStack.push(20);
        assertEqual(2, (int)testStack.size(), "Size after two pushes");

        assertEqual(20, testStack.top(), "Top element should be 20");
        testStack.pop();
        assertEqual(10, testStack.top(), "Top after pop should be 10");
    }

    void tearDown() override {
        cout << "  [TEARDOWN] Stack destroyed\n";
    }
};

class DatabaseTest : public TestCase {
    // Simulated database connection
    bool connected = false;

public:
    DatabaseTest() : TestCase("Database Connection") {}

protected:
    void setUp() override {
        cout << "  [SETUP] Connecting to test database\n";
        connected = true;
        // In real code: create test tables, insert fixtures
    }

    void executeTest() override {
        assertTrue(connected, "Should be connected to database");

        // Simulated query test
        int result = 42;  // Would be actual query result
        assertEqual(42, result, "SELECT answer FROM universe");
    }

    void tearDown() override {
