        connected = false;
    }
};

class FailingTest : public TestCase {
public:
    FailingTest() : TestCase("Intentional Failure") {}

protected:
    void executeTest() override {
        assertEqual(10, 5 + 5, "Basic math works");
        assertEqual(100, 50, "This will fail");  // Intentional failure
    }
};

// Test Runner
class TestRunner {
    vector<unique_ptr<TestCase>> tests;

public:
    void addTest(unique_ptr<TestCase> test) {
        tests.push_back(move(test));
    }

    void runAll() {
        int passed = 0, failed = 0;

        cout << "========== TEST SUITE ==========\n";

        for (auto& test : tests) {
            test->run();
            if (test->didPass()) passed++;
            else failed++;
        }

        cout << "\n========== SUMMARY ==========\n";
        cout << "Total: " << tests.size() << " | Passed: " << passed 
             << " | Failed: " << failed << "\n";
    }
};

int main() {
    TestRunner runner;

    runner.addTest(make_unique<StackTest>());
    runner.addTest(make_unique<DatabaseTest>());
    runner.addTest(make_unique<FailingTest>());

    runner.runAll();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Forward declarations
class Circle;
class Rectangle;
class Triangle;
class Group;

// Visitor Interface
class ShapeVisitor {
public:
    virtual ~ShapeVisitor() = default;
    virtual void visitCircle(Circle& circle) = 0;
    virtual void visitRectangle(Rectangle& rectangle) = 0;
    virtual void visitTriangle(Triangle& triangle) = 0;
    virtual void visitGroup(Group& group) = 0;
};

// Element Interface
class Shape {
public:
    virtual ~Shape() = default;
    virtual void accept(ShapeVisitor& visitor) = 0;
    virtual void draw() const = 0;
    virtual string getName() const = 0;
};

// Concrete Elements
class Circle : public Shape {
    double radius;
    double x, y;

public:
    Circle(double r, double x, double y) : radius(r), x(x), y(y) {}

    void accept(ShapeVisitor& visitor) override {
        visitor.visitCircle(*this);
    }

    void draw() const override {
        cout << "Drawing Circle at (" << x << "," << y << ") r=" << radius << "\n";
    }

    string getName() const override { return "Circle"; }
    double getRadius() const { return radius; }
    double getArea() const { return M_PI * radius * radius; }
    double getPerimeter() const { return 2 * M_PI * radius; }
    pair<double, double> getPosition() const { return {x, y}; }
};

class Rectangle : public Shape {
    double width, height;
    double x, y;

public:
    Rectangle(double w, double h, double x, double y) : width(w), height(h), x(x), y(y) {}

    void accept(ShapeVisitor& visitor) override {
        visitor.visitRectangle(*this);
    }

    void draw() const override {
        cout << "Drawing Rectangle at (" << x << "," << y << ") " << width << "x" << height << "\n";
    }

    string getName() const override { return "Rectangle"; }
    double getWidth() const { return width; }
    double getHeight() const { return height; }
    double getArea() const { return width * height; }
    double getPerimeter() const { return 2 * (width + height); }
    pair<double, double> getPosition() const { return {x, y}; }
};

class Triangle : public Shape {
    double a, b, c;
    double x, y;

public:
    Triangle(double sideA, double sideB, double sideC, double x, double y) 
        : a(sideA), b(sideB), c(sideC), x(x), y(y) {}

    void accept(ShapeVisitor& visitor) override {
        visitor.visitTriangle(*this);
    }

    void draw() const override {
        cout << "Drawing Triangle at (" << x << "," << y << ") sides=" << a << "," << b << "," << c << "\n";
    }

    string getName() const override { return "Triangle"; }
    double getArea() const {
        double s = (a + b + c) / 2;
        return sqrt(s * (s - a) * (s - b) * (s - c));
    }
    double getPerimeter() const { return a + b + c; }
    pair<double, double> getPosition() const { return {x, y}; }
};

// Composite Element
class Group : public Shape {
    vector<unique_ptr<Shape>> children;
    string name;

public:
    Group(const string& n) : name(n) {}

    void add(unique_ptr<Shape> shape) {
        children.push_back(move(shape));
    }

    void accept(ShapeVisitor& visitor) override {
        visitor.visitGroup(*this);
    }

    void draw() const override {
        cout << "Group '" << name << "' containing:\n";
        for (const auto& child : children) {
            child->draw();
        }
    }

    string getName() const override { return "Group:" + name; }
    const vector<unique_ptr<Shape>>& getChildren() const { return children; }
};

// Concrete Visitors
class AreaCalculator : public ShapeVisitor {
    double totalArea = 0;

public:
    void visitCircle(Circle& circle) override {
        totalArea += circle.getArea();
    }

    void visitRectangle(Rectangle& rectangle) override {
        totalArea += rectangle.getArea();
    }

    void visitTriangle(Triangle& triangle) override {
        totalArea += triangle.getArea();
    }

    void visitGroup(Group& group) override {
        for (const auto& child : group.getChildren()) {
            child->accept(*this);
        }
    }

    double getTotalArea() const { return totalArea; }
    void reset() { totalArea = 0; }
};

class PerimeterCalculator : public ShapeVisitor {
    double totalPerimeter = 0;

public:
    void visitCircle(Circle& circle) override {
        totalPerimeter += circle.getPerimeter();
    }

    void visitRectangle(Rectangle& rectangle) override {
        totalPerimeter += rectangle.getPerimeter();
    }

    void visitTriangle(Triangle& triangle) override {
        totalPerimeter += triangle.getPerimeter();
    }

    void visitGroup(Group& group) override {
        for (const auto& child : group.getChildren()) {
            child->accept(*this);
        }
    }

    double getTotalPerimeter() const { return totalPerimeter; }
};

class SVGExporter : public ShapeVisitor {
    stringstream svg;
    int indent = 0;

    string getIndent() const { return string(indent, ' '); }

public:
    void visitCircle(Circle& circle) override {
        auto [x, y] = circle.getPosition();
        svg << getIndent() << "<circle cx=\"" << x << "\" cy=\"" << y 
            << "\" r=\"" << circle.getRadius() << "\" />\n";
    }

    void visitRectangle(Rectangle& rectangle) override {
        auto [x, y] = rectangle.getPosition();
        svg << getIndent() << "<rect x=\"" << x << "\" y=\"" << y 
            << "\" width=\"" << rectangle.getWidth() 
            << "\" height=\"" << rectangle.getHeight() << "\" />\n";
    }

    void visitTriangle(Triangle& triangle) override {
        auto [x, y] = triangle.getPosition();
        svg << getIndent() << "<!-- Triangle at (" << x << "," << y << ") -->\n";
    }

    void visitGroup(Group& group) override {
        svg << getIndent() << "<g id=\"" << group.getName() << "\">\n";
        indent += 2;
        for (const auto& child : group.getChildren()) {
            child->accept(*this);
        }
        indent -= 2;
        svg << getIndent() << "</g>\n";
    }

    string getSVG() const {
        return "<svg xmlns=\"http://www.w3.org/2000/svg\">\n" + svg.str() + "</svg>";
    }
};

class MoveVisitor : public ShapeVisitor {
    double dx, dy;

public:
    MoveVisitor(double dx, double dy) : dx(dx), dy(dy) {}

    void visitCircle(Circle& circle) override {
        // Note: In real implementation, would need setter or mutable position
        cout << "  Moving Circle by (" << dx << "," << dy << ")\n";
    }

    void visitRectangle(Rectangle& rectangle) override {
        cout << "  Moving Rectangle by (" << dx << "," << dy << ")\n";
    }

    void visitTriangle(Triangle& triangle) override {
        cout << "  Moving Triangle by (" << dx << "," << dy << ")\n";
    }

    void visitGroup(Group& group) override {
        cout << "  Moving Group by (" << dx << "," << dy << ")\n";
        for (const auto& child : group.getChildren()) {
            child->accept(*this);
        }
    }
};

int main() {
    // Build scene
    auto scene = make_unique<Group>("Scene");

    auto shapes = make_unique<Group>("Shapes");
    shapes->add(make_unique<Circle>(5, 10, 10));
    shapes->add(make_unique<Rectangle>(20, 30, 50, 50));
    shapes->add(make_unique<Triangle>(3, 4, 5, 100, 100));

    auto moreShapes = make_unique<Group>("MoreShapes");
    moreShapes->add(make_unique<Circle>(10, 200, 200));

    scene->add(move(shapes));
    scene->add(move(moreShapes));

    cout << "=== Drawing ===\n";
    scene->draw();

    cout << "\n=== Area Calculation ===\n";
    AreaCalculator areaCalc;
    scene->accept(areaCalc);
    cout << "Total area: " << areaCalc.getTotalArea() << "\n";

    cout << "\n=== Perimeter Calculation ===\n";
    PerimeterCalculator perimCalc;
    scene->accept(perimCalc);
    cout << "Total perimeter: " << perimCalc.getTotalPerimeter() << "\n";

