#include <bits/stdc++.h>
using namespace std;

// Modern C++17 approach using std::variant and std::visit
// No inheritance needed - uses std::variant for type-safe unions

struct CircleV {
    double radius;
    double x, y;
    double area() const { return M_PI * radius * radius; }
};

struct RectangleV {
    double width, height;
    double x, y;
    double area() const { return width * height; }
};

struct TriangleV {
    double a, b, c;
    double x, y;
    double area() const {
        double s = (a + b + c) / 2;
        return sqrt(s * (s - a) * (s - b) * (s - c));
    }
};

using ShapeVariant = variant<CircleV, RectangleV, TriangleV>;

// Visitors as lambdas or function objects
struct AreaVisitor {
    double operator()(const CircleV& c) const { return c.area(); }
    double operator()(const RectangleV& r) const { return r.area(); }
    double operator()(const TriangleV& t) const { return t.area(); }
};

struct DrawVisitor {
    void operator()(const CircleV& c) const {
        cout << "Drawing Circle r=" << c.radius << " at (" << c.x << "," << c.y << ")\n";
    }
    void operator()(const RectangleV& r) const {
        cout << "Drawing Rectangle " << r.width << "x" << r.height 
             << " at (" << r.x << "," << r.y << ")\n";
    }
    void operator()(const TriangleV& t) const {
        cout << "Drawing Triangle sides=" << t.a << "," << t.b << "," << t.c 
             << " at (" << t.x << "," << t.y << ")\n";
    }
};

// Using overloaded pattern (C++17)
template<typename... Ts>
struct overloaded : Ts... { using Ts::operator()...; };

template<typename... Ts>
overloaded(Ts...) -> overloaded<Ts...>;

int main() {
    vector<ShapeVariant> shapes;
    shapes.push_back(CircleV{5, 10, 10});
    shapes.push_back(RectangleV{20, 30, 50, 50});
    shapes.push_back(TriangleV{3, 4, 5, 100, 100});

    cout << "=== Drawing with std::visit ===\n";
    for (const auto& shape : shapes) {
        visit(DrawVisitor{}, shape);
    }

    cout << "\n=== Area Calculation ===\n";
    double totalArea = 0;
    for (const auto& shape : shapes) {
        totalArea += visit(AreaVisitor{}, shape);
    }
    cout << "Total area: " << totalArea << "\n";

    cout << "\n=== Inline Lambda Visitor ===\n";
    for (const auto& shape : shapes) {
        visit(overloaded{
            [](const CircleV& c) { cout << "Circle area: " << c.area() << "\n"; },
            [](const RectangleV& r) { cout << "Rectangle area: " << r.area() << "\n"; },
            [](const TriangleV& t) { cout << "Triangle area: " << t.area() << "\n"; }
        }, shape);
    }

    return 0;
}

#include <bits/stdc++.h>
