// Forward declarations
class TaskView;
class TaskController;

// Model
class TaskModel {
    vector<string> tasks;
    vector<TaskView*> views;

public:
    void attach(TaskView* view) { views.push_back(view); }
    void detach(TaskView* view) {
        views.erase(remove(views.begin(), views.end(), view), views.end());
    }

    void addTask(const string& task) {
        tasks.push_back(task);
        notify("added", task);
    }

    void removeTask(int index) {
        if (index >= 0 && index < (int)tasks.size()) {
            string removed = tasks[index];
            tasks.erase(tasks.begin() + index);
            notify("removed", removed);
        }
    }

    void markComplete(int index) {
        if (index >= 0 && index < (int)tasks.size()) {
            tasks[index] += " [DONE]";
            notify("completed", tasks[index]);
        }
    }

    const vector<string>& getTasks() const { return tasks; }

private:
    void notify(const string& event, const string& data);
};

// View
class TaskView {
    TaskModel* model;
    TaskController* controller = nullptr;
    string viewName;

public:
    TaskView(const string& name, TaskModel* m) : viewName(name), model(m) {
        model->attach(this);
    }

    ~TaskView() {
        if (model) model->detach(this);
    }

    void setController(TaskController* ctrl) { controller = ctrl; }

    void update(const string& event, const string& data) {
        cout << "[" << viewName << " View] Event: " << event 
             << " | Data: " << data << "\n";
        render();
    }

    void render() {
        cout << "  --- " << viewName << " Task List ---\n";
        const auto& tasks = model->getTasks();
        if (tasks.empty()) {
            cout << "  (No tasks)\n";
        } else {
            for (size_t i = 0; i < tasks.size(); i++) {
                cout << "  [" << i << "] " << tasks[i] << "\n";
            }
        }
        cout << "  -------------------\n";
    }

    // User input simulation
    void userAddsTask(const string& task);
    void userRemovesTask(int index);
    void userMarksComplete(int index);
};

// Controller
class TaskController {
    TaskModel* model;

public:
    TaskController(TaskModel* m) : model(m) {}

    void addTask(const string& task) {
        if (!task.empty()) {
            model->addTask(task);
        }
    }

    void removeTask(int index) {
        model->removeTask(index);
    }

    void markComplete(int index) {
        model->markComplete(index);
    }
};

// Linking (normally in .cpp)
void TaskModel::notify(const string& event, const string& data) {
    for (auto* view : views) {
        view->update(event, data);
    }
}

void TaskView::userAddsTask(const string& task) {
    if (controller) controller->addTask(task);
}

void TaskView::userRemovesTask(int index) {
    if (controller) controller->removeTask(index);
}

void TaskView::userMarksComplete(int index) {
    if (controller) controller->markComplete(index);
}

int main() {
    TaskModel model;
    TaskController controller(&model);

    // Multiple views observing the same model
    TaskView cliView("CLI", &model);
    TaskView guiView("GUI", &model);

    cliView.setController(&controller);
    guiView.setController(&controller);

    cout << "=== Initial State ===\n";
    cliView.render();

    cout << "\n=== Adding Tasks ===\n";
    cliView.userAddsTask("Buy groceries");
    cliView.userAddsTask("Write report");

    cout << "\n=== Marking Complete ===\n";
    guiView.userMarksComplete(0);

    cout << "\n=== Removing Task ===\n";
    cliView.userRemovesTask(1);

    return 0;
}

