// Simplified MVVM demonstration with observer pattern for binding

template<typename T>
class Observable {
    T value;
    vector<function<void(const T&)>> observers;

public:
    Observable(const T& initial) : value(initial) {}

    void set(const T& newValue) {
        if (value != newValue) {
            value = newValue;
            for (auto& observer : observers) {
                observer(value);
            }
        }
    }

    const T& get() const { return value; }

    void bind(function<void(const T&)> observer) {
        observers.push_back(observer);
        observer(value);  // Initial notification
    }
};

// Model
class Product {
    string name;
    double basePrice;
    int stock;

public:
    Product(const string& n, double price, int s) : name(n), basePrice(price), stock(s) {}

    string getName() const { return name; }
    double getBasePrice() const { return basePrice; }
    int getStock() const { return stock; }
    void setStock(int s) { stock = s; }
};

// ViewModel
class ProductViewModel {
    Product& model;

public:
    Observable<string> displayName{""};
    Observable<string> displayPrice{""};
    Observable<string> stockStatus{""};
    Observable<bool> canPurchase{false};
    Observable<int> quantity{1};

    ProductViewModel(Product& p) : model(p) {
        updateFromModel();
    }

    void updateFromModel() {
        displayName.set(model.getName());

        stringstream priceSS;
        priceSS << fixed << setprecision(2) << "$" << model.getBasePrice();
        displayPrice.set(priceSS.str());

        if (model.getStock() == 0) {
            stockStatus.set("Out of Stock");
            canPurchase.set(false);
        } else if (model.getStock() < 10) {
            stockStatus.set("Only " + to_string(model.getStock()) + " left!");
            canPurchase.set(true);
        } else {
            stockStatus.set("In Stock");
            canPurchase.set(true);
        }
    }

    void purchase() {
        if (canPurchase.get() && model.getStock() >= quantity.get()) {
            model.setStock(model.getStock() - quantity.get());
            updateFromModel();
            cout << "[ViewModel] Purchase successful! Remaining: " << model.getStock() << "\n";
        }
    }

    void setQuantity(int q) {
        quantity.set(max(1, min(q, model.getStock())));
    }
};

