#include <bits/stdc++.h>
using namespace std;

// Domain Layer (innermost - no dependencies)
struct User {
    int id;
    string name;
    string email;

    bool isValid() const {
        return !name.empty() && email.find('@') != string::npos;
    }
};

// Repository Interface (defined in Domain, implemented in Data Access)
class IUserRepository {
public:
    virtual ~IUserRepository() = default;
    virtual optional<User> findById(int id) = 0;
    virtual vector<User> findAll() = 0;
    virtual void save(const User& user) = 0;
    virtual void remove(int id) = 0;
};

// Service Layer (Business Logic)
class UserService {
    IUserRepository& repository;

public:
    UserService(IUserRepository& repo) : repository(repo) {}

    User registerUser(const string& name, const string& email) {
        User user{0, name, email};
        if (!user.isValid()) {
            throw invalid_argument("Invalid user data");
        }

        // Business rule: check for duplicate emails
        auto allUsers = repository.findAll();
        for (const auto& u : allUsers) {
            if (u.email == email) {
                throw runtime_error("Email already registered");
            }
        }

        repository.save(user);
        return user;
    }

    User getUser(int id) {
        auto user = repository.findById(id);
        if (!user) {
            throw runtime_error("User not found");
        }
        return *user;
    }

    vector<User> listUsers() {
        return repository.findAll();
    }
};

// Data Access Layer
class InMemoryUserRepository : public IUserRepository {
    unordered_map<int, User> users;
    int nextId = 1;

public:
    optional<User> findById(int id) override {
        auto it = users.find(id);
        if (it != users.end()) return it->second;
        return nullopt;
    }

    vector<User> findAll() override {
        vector<User> result;
        for (const auto& [id, user] : users) {
            result.push_back(user);
        }
        return result;
    }

    void save(const User& user) override {
        if (user.id == 0) {
            User newUser = user;
            newUser.id = nextId++;
            users[newUser.id] = newUser;
        } else {
            users[user.id] = user;
        }
    }

    void remove(int id) override {
        users.erase(id);
    }
};

// Presentation Layer (API Controller)
class UserController {
    UserService& service;

public:
    UserController(UserService& svc) : service(svc) {}

    void handleCreate(const string& name, const string& email) {
        try {
            auto user = service.registerUser(name, email);
            cout << "[API] Created user: {id:" << user.id << ", name:\"" 
                 << user.name << "\", email:\"" << user.email << "\"}\n";
        } catch (const exception& e) {
            cout << "[API] Error: " << e.what() << "\n";
        }
    }

    void handleGet(int id) {
        try {
            auto user = service.getUser(id);
            cout << "[API] User: {id:" << user.id << ", name:\"" 
                 << user.name << "\", email:\"" << user.email << "\"}\n";
        } catch (const exception& e) {
            cout << "[API] Error: " << e.what() << "\n";
        }
    }

    void handleList() {
        auto users = service.listUsers();
        cout << "[API] Users list (" << users.size() << " items):\n";
        for (const auto& u : users) {
            cout << "  {id:" << u.id << ", name:\"" << u.name << "\"}\n";
        }
    }
};

int main() {
    // Wiring dependencies (normally done by DI container)
    InMemoryUserRepository repository;
    UserService service(repository);
    UserController controller(service);

    cout << "=== Layered Architecture Demo ===\n\n";

    cout << "--- Create Users ---\n";
    controller.handleCreate("Alice", "alice@example.com");
    controller.handleCreate("Bob", "bob@example.com");
    controller.handleCreate("", "invalid");  // Should fail validation
    controller.handleCreate("Charlie", "alice@example.com");  // Should fail duplicate

    cout << "\n--- List Users ---\n";
    controller.handleList();

    cout << "\n--- Get User ---\n";
    controller.handleGet(1);
    controller.handleGet(99);  // Not found

    return 0;
}

