#include <bits/stdc++.h>
using namespace std;

class ThreadPool {
    vector<thread> workers;
    queue<function<void()>> tasks;
    mutex queueMutex;
    condition_variable condition;
    bool stop = false;
    size_t activeTasks = 0;

public:
    ThreadPool(size_t numThreads) {
        for (size_t i = 0; i < numThreads; i++) {
            workers.emplace_back([this, i] {
                while (true) {
                    function<void()> task;
                    {
                        unique_lock<mutex> lock(queueMutex);
                        condition.wait(lock, [this] { return stop || !tasks.empty(); });

                        if (stop && tasks.empty()) return;

                        task = move(tasks.front());
                        tasks.pop();
                        activeTasks++;
                    }

                    cout << "[Worker " << i << "] Executing task\n";
                    task();

                    {
                        unique_lock<mutex> lock(queueMutex);
                        activeTasks--;
                    }
                }
            });
        }
    }

    ~ThreadPool() {
        {
            unique_lock<mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

    template<typename F, typename... Args>
    auto enqueue(F&& f, Args&&... args) -> future<decltype(f(args...))> {
        using return_type = decltype(f(args...));

        auto task = make_shared<packaged_task<return_type()>>(
            bind(forward<F>(f), forward<Args>(args)...)
        );

        future<return_type> result = task->get_future();

        {
            unique_lock<mutex> lock(queueMutex);
            if (stop) throw runtime_error("ThreadPool stopped");
            tasks.emplace([task]() { (*task)(); });
        }

        condition.notify_one();
        return result;
    }

    size_t pendingTasks() const {
        unique_lock<mutex> lock(queueMutex);
        return tasks.size();
    }

    size_t getActiveTasks() const {
        unique_lock<mutex> lock(queueMutex);
        return activeTasks;
    }
};

int main() {
    ThreadPool pool(4);

    cout << "=== Thread Pool Demo ===\n\n";

    vector<future<int>> results;

    // Submit tasks
    for (int i = 0; i < 8; i++) {
        results.push_back(pool.enqueue([i] {
            this_thread::sleep_for(chrono::milliseconds(100));
            cout << "  Task " << i << " completed by thread " 
                 << this_thread::get_id() << "\n";
            return i * i;
        }));
    }

    cout << "Submitted 8 tasks, pending: " << pool.pendingTasks() << "\n";

    // Collect results
    cout << "\n=== Results ===\n";
    for (size_t i = 0; i < results.size(); i++) {
        cout << "Task " << i << " result: " << results[i].get() << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

template<typename T>
class BoundedBuffer {
    queue<T> buffer;
    size_t capacity;
    mutex mtx;
    condition_variable notFull;
    condition_variable notEmpty;
    bool done = false;

public:
    BoundedBuffer(size_t cap) : capacity(cap) {}

    void produce(T item) {
        unique_lock<mutex> lock(mtx);
        notFull.wait(lock, [this] { return buffer.size() < capacity || done; });

        if (done) return;

        buffer.push(move(item));
        cout << "[Producer] Produced item. Buffer: " << buffer.size() << "/" << capacity << "\n";
        notEmpty.notify_one();
    }

    bool consume(T& item) {
        unique_lock<mutex> lock(mtx);
        notEmpty.wait(lock, [this] { return !buffer.empty() || done; });

        if (buffer.empty() && done) return false;

        item = move(buffer.front());
        buffer.pop();
        cout << "[Consumer] Consumed item. Buffer: " << buffer.size() << "/" << capacity << "\n";
        notFull.notify_one();
        return true;
    }

    void shutdown() {
        unique_lock<mutex> lock(mtx);
        done = true;
        notEmpty.notify_all();
        notFull.notify_all();
    }
};

int main() {
    BoundedBuffer<int> buffer(3);

    thread producer([&buffer] {
        for (int i = 1; i <= 6; i++) {
            buffer.produce(i);
            this_thread::sleep_for(chrono::milliseconds(50));
        }
        buffer.shutdown();
    });

    thread consumer([&buffer] {
        int item;
        while (buffer.consume(item)) {
            cout << "  [Consumer] Processing item: " << item << "\n";
            this_thread::sleep_for(chrono::milliseconds(100));
        }
        cout << "[Consumer] Shutting down\n";
    });

    producer.join();
    consumer.join();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class ReadWriteLock {
    mutex mtx;
    condition_variable cv;
    int readers = 0;
    int writers = 0;
    int waitingWriters = 0;

public:
    void lockRead() {
        unique_lock<mutex> lock(mtx);
        cv.wait(lock, [this] { return writers == 0 && waitingWriters == 0; });
        readers++;
    }

    void unlockRead() {
        unique_lock<mutex> lock(mtx);
        readers--;
        if (readers == 0) {
            cv.notify_all();
        }
    }

    void lockWrite() {
        unique_lock<mutex> lock(mtx);
        waitingWriters++;
        cv.wait(lock, [this] { return readers == 0 && writers == 0; });
        waitingWriters--;
        writers++;
    }

    void unlockWrite() {
        unique_lock<mutex> lock(mtx);
        writers--;
        cv.notify_all();
    }
};

template<typename T>
class ThreadSafeData {
    T data;
    ReadWriteLock rwLock;

public:
    ThreadSafeData(const T& initial) : data(initial) {}

    T read() {
        rwLock.lockRead();
        T result = data;
        rwLock.unlockRead();
        return result;
    }

    void write(const T& newData) {
        rwLock.lockWrite();
        data = newData;
        rwLock.unlockWrite();
    }

    template<typename Func>
    void modify(Func&& f) {
        rwLock.lockWrite();
        f(data);
        rwLock.unlockWrite();
    }
};

int main() {
    ThreadSafeData<map<string, int>> cache({{"key1", 100}, {"key2", 200}});

    vector<thread> readers;
    vector<thread> writers;

    // Spawn readers
    for (int i = 0; i < 5; i++) {
        readers.emplace_back([&cache, i] {
            for (int j = 0; j < 3; j++) {
                auto data = cache.read();
                cout << "[Reader " << i << "] Read " << data.size() << " items\n";
                this_thread::sleep_for(chrono::milliseconds(10));
            }
        });
    }

    // Spawn writers
    for (int i = 0; i < 2; i++) {
        writers.emplace_back([&cache, i] {
            cache.modify([i](map<string, int>& data) {
                data["writer_" + to_string(i)] = i * 100;
                cout << "[Writer " << i << "] Added new key\n";
            });
            this_thread::sleep_for(chrono::milliseconds(50));
        });
    }

    for (auto& t : readers) t.join();
    for (auto& t : writers) t.join();

    auto finalData = cache.read();
    cout << "\nFinal cache has " << finalData.size() << " items\n";

    return 0;
}

