    worker.join();

    // Shared future (multiple consumers)
    cout << "\n=== Shared Future ===\n";
    shared_future<string> shared = async(launch::async, [] {
        return string("Shared Data");
    });

    thread t1([shared] { cout << "Thread 1: " << shared.get() << "\n"; });
    thread t2([shared] { cout << "Thread 2: " << shared.get() << "\n"; });

    t1.join();
    t2.join();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Simplified Actor implementation
class Actor {
    thread worker;
    queue<function<void()>> mailbox;
    mutex mtx;
    condition_variable cv;
    atomic<bool> running{true};
    string name;

public:
    Actor(const string& n) : name(n) {
        worker = thread([this] {
            while (running) {
                function<void()> message;
                {
                    unique_lock<mutex> lock(mtx);
                    cv.wait(lock, [this] { return !mailbox.empty() || !running; });
                    if (!running && mailbox.empty()) return;
                    message = move(mailbox.front());
                    mailbox.pop();
                }
                message();
            }
        });
    }

    virtual ~Actor() {
        running = false;
        cv.notify_all();
        if (worker.joinable()) worker.join();
    }

    void send(function<void()> message) {
        {
            unique_lock<mutex> lock(mtx);
            mailbox.push(move(message));
        }
        cv.notify_one();
    }

    string getName() const { return name; }
};

// Bank Account Actor
class BankAccount : public Actor {
    double balance = 0;
    vector<string> transactionLog;

public:
    BankAccount(const string& name) : Actor(name) {}

    void deposit(double amount) {
        send([this, amount] {
            balance += amount;
            transactionLog.push_back("+" + to_string(amount));
            cout << "[" << getName() << "] Deposited $" << amount 
                 << " | Balance: $" << balance << "\n";
        });
    }

    void withdraw(double amount) {
        send([this, amount] {
            if (balance >= amount) {
                balance -= amount;
                transactionLog.push_back("-" + to_string(amount));
                cout << "[" << getName() << "] Withdrew $" << amount 
                     << " | Balance: $" << balance << "\n";
            } else {
                cout << "[" << getName() << "] Insufficient funds for $" << amount 
                     << " | Balance: $" << balance << "\n";
            }
        });
    }

    void transferTo(BankAccount& other, double amount) {
        send([this, &other, amount] {
            if (balance >= amount) {
                balance -= amount;
                transactionLog.push_back("->" + to_string(amount));
                cout << "[" << getName() << "] Transferring $" << amount 
                     << " to " << other.getName() << "\n";
                other.deposit(amount);
            }
        });
    }

    void getBalance(function<void(double)> callback) {
        send([this, callback] {
            callback(balance);
        });
    }
};

int main() {
    cout << "=== Actor Model Demo ===\n\n";

    BankAccount alice("Alice");
    BankAccount bob("Bob");

    alice.deposit(1000);
    bob.deposit(500);

    this_thread::sleep_for(chrono::milliseconds(50));

    alice.withdraw(200);
    alice.transferTo(bob, 300);
    bob.withdraw(1000);  // Should fail

    this_thread::sleep_for(chrono::milliseconds(100));

    cout << "\n=== Final Balances ===\n";
    promise<double> aliceBalance, bobBalance;
    alice.getBalance([&aliceBalance](double b) { aliceBalance.set_value(b); });
    bob.getBalance([&bobBalance](double b) { bobBalance.set_value(b); });

    cout << "Alice: $" << aliceBalance.get_future().get() << "\n";
    cout << "Bob: $" << bobBalance.get_future().get() << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    const int numThreads = 4;
    barrier syncPoint(numThreads);
    atomic<int> phase{0};

    cout << "=== Barrier Synchronization Demo ===\n\n";

    vector<thread> threads;
    for (int i = 0; i < numThreads; i++) {
        threads.emplace_back([i, &syncPoint, &phase] {
            // Phase 1: Data loading
            cout << "[Thread " << i << "] Loading data...\n";
            this_thread::sleep_for(chrono::milliseconds(100 + i * 50));
            cout << "[Thread " << i << "] Data loaded, waiting at barrier\n";

            syncPoint.arrive_and_wait();

            // Phase 2: Processing (all threads start together)
            cout << "[Thread " << i << "] Starting processing phase\n";
            this_thread::sleep_for(chrono::milliseconds(100));
            cout << "[Thread " << i << "] Processing complete, waiting at barrier\n";

            syncPoint.arrive_and_wait();

            // Phase 3: Aggregation
            cout << "[Thread " << i << "] Aggregating results\n";
        });
    }

    for (auto& t : threads) t.join();
    cout << "\nAll phases complete!\n";

    return 0;
}

